-- GENERATED by `wfi generate` from data/quest/quest-0000.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [6] = { "Una taglia su Garrick Padfoot", "Uccidi Garrick Padfoot e porta la sua testa a Deputy Willem, alla Northshire Abbey.", "Garrick Padfoot, un tagliagole che da settimane tormenta i nostri contadini e mercanti, è stato visto in una baracca vicino ai vigneti, a est dell'abbazia, oltre il ponte. Portami la testa di quel furfante e guadagnati la taglia!\n\nMa stai in guardia, {name}. Garrick ha radunato intorno a sé una banda di delinquenti. Non sarà facile arrivare fino a lui.", "Hai trovato la baracca di Garrick? Siamo finalmente liberi da quel furfante?", "Ah! L'hai preso! Hai reso un grande servizio a Elwynn, e ora una bella taglia è tutta tua!", 0xd9a1ea2f, 0xb35875a3, 0x674275ec, 0xe205dce0, 0x8edda1cf, "....." },
  [7] = { "Ripulire il campo dei kobold", "Uccidi 10 Kobold Vermin, poi torna da Marshal McBride.", "Il tuo primo compito sarà fare pulizia, {name}. Un clan di kobold ha infestato i boschi a nord. Vai là e combatti i Kobold Vermin che trovi. Riducine il numero, così che un giorno potremo cacciarli da Northshire.", "Come va la caccia, {name}? Hai trovato e sconfitto quei parassiti?", "Ben fatto, <cittadino/cittadina>. Quei kobold sono ladri e codardi, ma in gran numero sono una minaccia per noi. E agli umani di Stormwind non serve un'altra minaccia.\n\nPer averli sconfitti, hai la mia gratitudine.", 0x5d10a531, 0xc0a62578, 0x54635c79, 0x4eb51373, 0xb52dae46, "....." },
  [9] = { "I campi della morte", "Farmer Saldean vuole che tu uccida 20 Harvest Watchers.", "Guarda cos'è successo a questo posto! Un tempo queste terre erano abitate da brava gente di campagna. Ma quei maledetti ladri li hanno cacciati tutti. Non me, però! Solo che a quanto pare alcuni Harvest Watchers si sono presi i campi.\n\nSe te la senti di lavorare, vorrei che andassi a ucciderne 20. Torna quando hai finito, per la paga. Se hai finito con quelli del mio campo, ripulisci anche i campi vicini.", "Ah, vedo che sei <tornato/tornata>! Spero che tu abbia lavorato sodo per ripulire quei campi dagli Harvest Watchers. Ne hai già uccisi 20?", "Bel lavoro, amico. Ti sei <guadagnato/guadagnata> la paga. Chissà, forse Westfall tornerà a prosperare.", 0xe8dc51f9, 0xb1fcb3e9, 0xc49a0580, 0x0e0d21d8, 0x9ce4bf4e, "....." },
  [11] = { "Taglia sugli gnoll Riverpaw", "Porta 8 Painted Gnoll Armbands a Deputy Rainer, alle Barracks.", "Gli gnoll, creature brutali che non hanno nulla da fare in queste terre, sono stati avvistati lungo i confini della Elwynn Forest. Un grosso branco, molto più numeroso di quanto possiamo affrontare da soli, ha infestato i boschi a sud della torre di guardia laggiù. Un altro gruppo ha infestato le zone vicino allo Stone Cairn Lake, a est.\n\nLa Stormwind Army ricompenserà chiunque aiuti a ucciderli. Portami i loro Painted Gnoll Armbands come prova dell'impresa.", "Salute, {name}. Hai ucciso degli gnoll...?", "Vedo che ti sei <dato/data> da fare! Hai la nostra gratitudine, {name}.", 0x9b53bb87, 0x8f6713f0, 0x9259d68e, 0x11769f64, 0xc6ac4114, "....." },
  [12] = { "La People's Militia", "Gryan Stoutmantle vuole che tu uccida 15 Defias Trappers e 15 Defias Smugglers, poi torni da lui a Sentinel Hill.", "La People's Militia ha un solo scopo: difendere le terre di Westfall e riportare la pace nei dintorni. Purtroppo, il prezzo della pace è spesso il sangue.\n\nUno dei miei esploratori mi ha avvertito che una banda di Defias Trappers sta seminando il caos qui vicino. Ho notizie di avvistamenti di Defias Trapper vicino alla Jangolode Mine, a nord-ovest, alla Molsen Farm e alla Furlbrow's Pumpkin Farm. Se vuoi unirti alle nostre file, uccidi 15 Defias Trappers e 15 Defias Smugglers, poi torna da me.", "Forse non sono stato chiaro, recluta. Per dimostrare il tuo valore come servitore della People's Militia e della Luce devi uccidere 15 Defias Trappers e 15 Defias Smugglers, poi tornare da me a cose fatte.", "Ben fatto, {name}. Il mio esploratore ha visto le tue gesta valorose. Finora stai dando ottima prova di te.", 0xe151209f, 0x16896ec7, 0x8596ea3e, 0xecfd7c3c, 0x84930ba2, "....." },
  [13] = { "La People's Militia", "Gryan Stoutmantle vuole che tu uccida 15 Defias Pillagers e 15 Defias Looters e torni da lui a Sentinel Hill.", "Una banda di feroci Defias Pillagers è stata vista saccheggiare la Gold Coast Quarry, Moonbrook e l'Alexston Farmstead. La People's Militia non tollererà un simile comportamento. Parti subito, {name}, e fai sentire la presenza della Luce a Westfall.\n\nLa Gold Coast Quarry è vicino alla riva, a ovest della torre. Come prossimo passo del tuo addestramento, voglio che tu uccida 15 di quei luridi Defias Pillagers e 15 Defias Looters.", "Non abbiamo tempo per parlare, {name}. I Defias Pillagers negano alla gente di Westfall la pace e la prosperità che merita. Assicurati che almeno 15 Defias Pillagers e 15 Defias Looters siano stati uccisi. Sarà un messaggio chiaro: la corruzione qui non è gradita.", "Il tuo valore per la People's Militia è stato confermato dalle tue azioni coraggiose.", 0xe151209f, 0x6d788fcc, 0x1eea16a0, 0x687557dd, 0xb859c405, "....." },
  [14] = { "La People's Militia", "Gryan Stoutmantle vuole che tu uccida 15 Defias Highwaymen, 5 Defias Pathstalkers e 5 Defias Knuckledusters, poi torni da lui a Sentinel Hill.", "Alcuni Defias ci sono sfuggiti. Il mio esploratore più fidato riferisce che questi Defias hanno razziato e saccheggiato le campagne, fino alla parte meridionale di Westfall. Crediamo che si nascondano nelle Dagger Hills, a tramare la loro prossima mossa. Uccidi quei miserabili in nome della People's Militia.", "{name}, non è il momento per le chiacchiere. Se vuoi ancora dimostrare il tuo valore alla People's Militia devi uccidere i Defias di cui ti ho parlato prima. Torna da me quando avrai compiuto il tuo dovere.", "Quando lasciai le terre corrotte di Lordaeron, tornai in patria e trovai una situazione cupa. Ma c'è ancora speranza per Westfall. Come dimostra il tuo valore in battaglia, è evidente che servi la nostra causa con onore. È con grande orgoglio che ti accolgo nella People's Militia. Che la Luce risplenda su di te.", 0xe151209f, 0x78ad5d7f, 0xab47f493, 0xa480f62a, 0xf947b26e, "....." },
  [15] = { "Indagini a Echo Ridge", "Uccidi 10 Kobold Workers, poi torna a fare rapporto a Marshal McBride.", "{name}, i miei esploratori dicono che l'infestazione di kobold è più estesa di quanto pensassimo. Un gruppo di Kobold Workers si è accampato vicino alla Echo Ridge Mine, a nord.\n\nVai alla miniera e toglili di mezzo. Sappiamo che sono almeno 10. Uccidili, controlla se ce ne sono altri, poi torna a farmi rapporto.", "Sei <andato/andata> alle miniere? Sei <pronto/pronta> a fare rapporto?", "Non mi piace sentire di tutti questi kobold nella nostra miniera. Non ne verrà niente di buono. Ecco, prendi questo come compenso, e quando sei <pronto/pronta> parlami di nuovo. Vorrei che tornassi alle miniere ancora una volta...", 0xb43a6289, 0xa368f704, 0x2cb816b5, 0x063df25d, 0xf0b6a1c7, "....." },
  [16] = { "Da bere per Gerard", nil, nil, "Lavorare nei campi mette sete, e cerco sempre acqua fresca di sorgente.\n\nSe ne hai un po', sono disposto a fare uno scambio.", "Grazie, {name}! E torna se vuoi fare un altro scambio.", 0x8a697a25, nil, nil, 0x6a289e06, 0x46e9e47e, ".mm.." },
  [18] = { "La confraternita dei ladri", "Porta 12 Red Burlap Bandanas a Deputy Willem, fuori dalla Northshire Abbey.", "Da poco un nuovo gruppo di ladri si aggira intorno a Northshire. Si fanno chiamare Defias Brotherhood e sono stati visti oltre il fiume, a est.\n\nNon so cosa stiano tramando, ma di sicuro niente di buono! Portami le bandane che indossano e ti ricompenserò con un'arma.", "Hai già raccolto quelle bandane per me?", "Vedo che hai portato qualche bandana. La Stormwind Army ti è grata per il tuo aiuto.", 0x2f1eb64e, 0x0376329b, 0x0ff5818f, 0x59c5a6d0, 0x9eec7aad, "....." },
  [19] = { nil, "Porta la Tharil'zun's Head a Marshal Marris, a Redridge.", "I Blackrock Outrunners e i Renegades tendono imboscate tra qui e la Stonewatch Keep. Il capo degli Outrunners è un orco di nome Tharil'zun: è lui che vogliamo. Portami la testa di Tharil'zun!", "La pressione degli orchi Blackrock è ancora forte. Ma almeno ci hai liberati di Tharil'zun?", "Tharil'zun era un orco feroce e astuto. Ben fatto: di sicuro non è caduto facilmente. Ecco la tua ricompensa, {name}.", nil, 0x7c13c137, 0x8b3cf21c, 0x55e47621, 0x3c4e5d23, "m...." },
  [20] = { "La minaccia dei Blackrock", "Porta 10 Battleworn Axes a Marshal Marris, a Lakeshire.", "Gli orchi Blackrock sono arrivati dalle Burning Steppes e si sono presi la Stonewatch Keep, a nord. Da lì razziano le zone a nord di Lakeshire e tengono i suoi abitanti chiusi in paese, rinchiusi come bestiame.\n\nAiuta a liberare Lakeshire da questa minaccia. Uccidi questi orchi Blackrock e portami 10 delle loro Battleworn Axes come prova.\n\nE anche se i Blackrock ci minacciano da nord, abbiamo notizie di altri nell'angolo sud-orientale di Redridge. Se ne trovi anche lì, dai la caccia pure a loro.", "Hai ucciso degli orchi, {name}? Se è così, fammi vedere...", "Così abbiamo molti meno orchi di cui preoccuparci, grazie.", 0xeb0d5482, 0x427516c3, 0xdcc24f55, 0x9b1e452c, 0x1c8fce29, "....." },
  [21] = { "Scaramuccia a Echo Ridge", "Uccidi 12 Kobold Laborers, poi torna da Marshal McBride alla Northshire Abbey.", "Le tue indagini hanno dimostrato che la Echo Ridge Mine va ripulita. Torna alla miniera e aiuta a liberarla dai kobold.\n\nNon perdere tempo, {name}. Più a lungo i kobold restano indisturbati nella miniera, più saldamente mettono radici a Northshire.", "So che è un lavoro sanguinoso, {name}, ma è vitale per la sicurezza di Northshire. Sei <pronto/pronta> a fare rapporto?", "Ancora una volta hai conquistato il mio rispetto e la gratitudine della Stormwind Army. Forse nella miniera ci sono ancora dei kobold, ma radunerò altri soldati contro di loro. Abbiamo altri compiti per te.", 0xa7a12dbe, 0x26b99d1f, 0xeb16bc2b, 0xf565255c, 0x019e5401, "....." },
  [22] = { nil, "A Salma Saldean servono 8 Goretusk livers per preparare una Goretusk Liver Pie.", "Le cipolle sono sbucciate. L'aglio è tritato. Il rosmarino è pestato. La crosta è cotta. L'aneto è sminuzzato. Il sugo sobbolle. Ora per il mio famoso pasticcio di carne mi servono solo 8 Goretusk Livers!", "Per il mio famoso pasticcio di carne mi servono solo 8 Goretusk Livers!", "Sono perfetti, {name}! Grazie mille. Stasera io e Farmer Saldean faremo un banchetto. Ed ecco qualcosina per te, per il duro lavoro. Pensavi davvero che ti avrei lasciato a pancia vuota, {class}?", nil, 0x0a34a00f, 0xa7490995, 0xe421b346, 0x2f880112, "m...." },
  [33] = { "Lupi oltre il confine", "Porta 8 pezzi di Tough Wolf Meat a Eagan Peltskinner, fuori dalla Northshire Abbey.", "Odio quei maledetti lupi dei boschi! Però le bistecche di lupo mi piacciono proprio... Portami della Tough Wolf Meat e te la scambierò con qualcosa che ti tornerà utile.\n\nLa Tough Wolf Meat si ricava cacciando i lupi dei boschi e i lupi giovani che vagano per le campagne di Northshire.", "Ehi, {name}. Comincio ad avere fame... hai preso quella Tough Wolf Meat?", "Hai lavorato sodo! Non vedo l'ora di cucinare quella carne di lupo...\n\nHo qui alcune cose che potrebbero interessarti: scegli pure!", 0xf2272f07, 0xdf199ead, 0x5ce8cfac, 0xf5cb8e2e, 0x63c80a97, "....." },
  [34] = { "Un ospite sgradito", "Martie Jainrose di Lakeshire vuole che tu uccida Bellygrub. Portale la sua zanna come prova.", "Ancora una volta il mio orto è stato calpestato e saccheggiato. E so chi è il bruto che lo fa. È quel maledetto cinghiale, quello che Marshal Marris ha preso a chiamare Bellygrub.\n\nOra non potrò ripiantare i narcisi fino alla prossima stagione. Rovinati! Tutto rovinato da quel cinghiale molesto. Metti fine a quella peste! Mostrami la sua zanna e sarò felice di ricompensarti. Sembra che passi il tempo a cercare cibo nel campo a sud-ovest di Lakeshire, ma ogni tanto si spinge fin qui, nel mio orto.", "Bellygrub continua a fare danni, o sei <riuscito/riuscita> a liberare Lakeshire da quella peste una volta per tutte?", "Finalmente la minaccia è sistemata! Grazie, {name}, mi hai reso un grande servizio. Quest'anno l'orto sarà in piena fioritura!", 0x5c809bb5, 0xabb3c5cc, 0xd5dec96a, 0x26e466ea, 0x3fd295c2, "....." },
  [35] = { "Altre preoccupazioni", "Marshal Dughan vuole che tu parli con Guard Thomas.", "Se temi che le voci sui murloc siano vere, allora fai così: vai al ponte orientale di Elwynn e parla con Guard Thomas. È di stanza al ponte da una settimana e saprà com'è la situazione nella zona.\n\nPortami il suo rapporto.", nil, "Sì, i murloc si sono stabiliti lungo i torrenti della parte orientale di Elwynn e nei dintorni. Non sappiamo perché siano qui, ma sono aggressivi e almeno in parte intelligenti.", 0xbf37aefc, 0xd1c199f2, 0x0d41f7ae, nil, 0xfbe5b854, "...m." },
  [36] = { nil, "Verna Furlbrow vuole che tu consegni la sua ricetta della Westfall Stew a Salma Saldean.", "Non avrei mai pensato che sarebbe arrivato il giorno in cui avrei lasciato la fattoria. Ma i campi sono invasi dai ladri, ed è troppo pericoloso restare qui. Appena Farmer Furlbrow avrà aggiustato il carro, ce ne andremo.\n\nMi faresti un favore? Lascia che ti scarabocchi la mia ricetta della Westfall Stew. Ti prego, portala a Salma Saldean, nella fattoria laggiù. La fattoria dei Saldean è appena oltre il bivio.", "Mi mancherà tanto quella Verna Furlbrow. Per caso l'hai vista venendo qui?", "Quella Verna è sempre stata una ragazza così dolce. Ci mancherà qui a Westfall ma, detto tra noi, in fondo è una ragazza di città, e Stormwind le starà a pennello. Ma basta pettegolezzi! Ora possiamo preparare la Westfall Stew!", nil, 0xd3f82a15, 0xce62c0a2, 0xdfbf0990, 0xd01407d2, "m...." },
  [37] = { "Trovare le guardie scomparse", "Guard Thomas vuole che tu risalga il fiume verso nord e cerchi le due guardie scomparse, Rolf e Malakai.", "Qualche giorno fa abbiamo mandato due guardie, Rolf e Malakai, a indagare lungo il fiume, e non sono ancora tornate. Per completare il mio rapporto devo sapere che fine hanno fatto.\n\nRisali il fiume verso nord e trova le guardie... o quello che ne resta.", nil, "Anche se il cadavere è stato in gran parte spogliato, lì vicino c'è un medaglione con incise le parole: \"Footman Malakai Stone\".", 0xbd0b84c3, 0xc79cfdb3, 0x96ec21d0, nil, 0xf410e026, "...m." },
  [38] = { nil, "Salma Saldean vuole 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes e 3 Okra.", "Aiutami a preparare la Westfall Stew! Torna con questi ingredienti:\n\n3 Stringy Vulture Meat\n\n3 Goretusk Snouts\n\n3 Murloc Eyes\n\n3 Okra", "Torna con questi ingredienti:\n\n3 Stringy Vulture Meat\n\n3 Goretusk Snouts\n\n3 Murloc Eyes\n\n3 Okra", "Questa Okra renderà il brodo bello denso! Ora aggiungiamo la Stringy Vulture Meat, qualche Murloc Eyes e quei deliziosi Goretusk Snouts. Ed è fatta! Per tutto il tuo aiuto, {name}, voglio che prenda tu la prima porzione di oggi di Westfall Stew!", nil, 0x1fd3a0f2, 0xe339c1dc, 0xbc377ac8, 0xe18bc596, "m...." },
  [39] = { "Consegnare il rapporto di Thomas", "Fai rapporto a Marshal Dughan, a Goldshire.", "Riferisci a Marshal Dughan della morte di Malakai e Rolf, e digli che con le truppe che abbiamo ora non possiamo contenere i murloc nella parte orientale di Elwynn.\n\nSo che non abbiamo molti uomini da mandare, ma speriamo che Dughan trovi qualcuno.", nil, "Mmm, queste notizie sono preoccupanti. Le nostre difese sono già allo stremo, e perdere Rolf e Malakai per colpa di quei murloc ci mette in una posizione ancora peggiore.\n\nSe le cose non migliorano, entro la fine della settimana si combatterà a Goldshire!", 0x25228270, 0x3f1aa863, 0x2d7986ad, nil, 0xae2657cb, "...m." },
  [40] = { "Un pericolo che sa di pesce", "Remy \"Two Times\" vuole che tu parli con Marshal Dughan, a Goldshire.", "{name}, c'è una nuova minaccia nella Elwynn Forest! I murloc risalgono i torrenti della parte orientale di Elwynn, fanno scappare i pesci e aggrediscono la brava gente!\n\nHo avvertito Marshal Dughan, ma lui si preoccupa di più degli gnoll e dei banditi. Non è convinto che i murloc siano un pericolo.\n\nTi prego, {name}, parla con Dughan e convincilo a mandare altre truppe a est!", nil, "Sì, ho parlato con Remy. Lo rispetto come mercante, ma le voci sui murloc a est sono state a dir poco vaghe.\n\nPrendo nota delle tue preoccupazioni, ma a meno che non riceva un rapporto militare su una minaccia dei murloc, non possiamo permetterci di mandare altre truppe a est.", 0x02cfe285, 0x67e1f5a8, 0xb8d781bd, nil, 0xf6272f28, "...m." },
  [45] = { "Scoprire la sorte di Rolf", "Cerca Rolf nel villaggio dei murloc, o segni della sua morte.", "Cercando ancora nella zona, trovi impronte palmate che vanno verso est lungo la riva dello Stone Cairn Lake. In lontananza, a est, riesci a malapena a scorgere un villaggio di murloc.\n\nForse è lì che Rolf ha trovato la sua fine...", nil, "Al collo del cadavere trovi un medaglione di metallo con incise le parole \"Footman Rolf Hartford.\"", 0x119e499d, 0x93412d0c, 0xbf0a2396, nil, 0x0692a2fa, "...m." },
  [46] = { "Taglia sui murloc", "Porta 8 Torn Murloc Fins a Guard Thomas, al ponte orientale di Elwynn.", "La Stormwind Army ha messo una taglia sui murloc lurker e forager di Elwynn. Fanne strage e portami le loro Torn Murloc Fins: la Stormwind Army ti ricompenserà bene.\n\nI murloc hanno costruito un villaggio allo Stone Cairn Lake, a nord di qui, e un altro a sud, dove il torrente si divide.", "Come va la caccia, {name}?", "Hai le pinne? Ottimo! Marshal Dughan è in ansia per la situazione dei murloc nella parte orientale di Elwynn, e mi piacerebbe dirgli che la stiamo mettendo sotto controllo.\n\nLe tue azioni hanno contribuito a renderlo possibile.", 0xd7ee6932, 0x320c64a3, 0x05a40606, 0xd84cca78, 0xff08c2c6, "....." },
  [47] = { "Scambio di Gold Dust", "Porta 10 Gold Dust a Remy \"Two Times\", a Goldshire. La Gold Dust si raccoglie dai kobold della Elwynn Forest.", "I kobold da queste parti a volte si portano dietro della Gold Dust. Mi farebbe proprio comodo: portamene un bel po' e ti farò il miglior prezzo in città... il miglior prezzo in città!\n\nTrovi i kobold nella Fargodeep Mine, a sud, e intorno alla Jasperlode Mine, a nord-est.", "Psst! Hai quella Gold Dust per me... per me?", "Grazie per la polvere, {name}. Ecco i tuoi soldi, e... ecco un pegno da parte di alcuni miei soci. Potrebbe tornarti utile... utile.", 0x6fc1c811, 0x54bcff94, 0xcbdc7c22, 0xfc397987, 0x26e50fd4, "....." },
  [48] = { "Ambra dolce", "Porta la Holy Spring Water a Grimbooze Thunderbrew.", "A sud, dove i tralci serpeggiano intrecciati\n\nC'è un pozzo nascosto, dagli abissi più celati\n\nPuro come la sacra figlia della Luce\n\nPortami la Holy Spring Water che lì riluce.", "Hic! Oh oh! Vuoi il bis?\n\nA sud, dove i tralci serpeggiano intrecciati\n\nC'è un pozzo nascosto, dagli abissi più celati\n\nPuro come la sacra figlia della Luce\n\nPortami la Holy Spring Water che lì riluce.", "Hic! Oh oh!", 0xcfa75457, 0x4e77cd9b, 0x13610a88, 0xb098103f, 0x677f464a, "....." },
  [49] = { "Ambra dolce", "Grimbooze Thunderbrew vuole un Sack of Barley, un Sack of Rye e un Sack of Corn.", "D'ambra è il colore del mio amore più antico\n\nCome l'ultima brace del tramonto, ti dico\n\nPerché il mio amore possa infine sbocciare\n\nOrzo, segale e mais, un sacco di ciascuno mi devi portare.", "Il bis? Ma certo!\n\nD'ambra è il colore del mio amore più antico\n\nCome l'ultima brace del tramonto, ti dico\n\nPerché il mio amore possa infine sbocciare\n\nOrzo, segale e mais, un sacco di ciascuno mi devi portare.", "Hic! Oh oh!", 0xcfa75457, 0x95311fad, 0x952da726, 0x2aecfde8, 0x6787a76a, "....." },
  [50] = { "Ambra dolce", "Grimbooze Thunderbrew vuole del Truesilver.", "Mescolerò e rimescolerò finché il mosto sarà pronto\n\nSarà la nostra scorta segreta, senza alcun sconto\n\nUn alambicco di metallo forte va forgiato\n\nPortami del Truesilver e il canto sarà terminato.", "Il bis per te? Ma certo, amico!\n\nMescolerò e rimescolerò finché il mosto sarà pronto\n\nSarà la nostra scorta segreta, senza alcun sconto\n\nUn alambicco di metallo forte va forgiato\n\nPortami del Truesilver e il canto sarà terminato.", "Hic! Oh oh!", 0xcfa75457, 0x4e472b5f, 0x915c986b, 0x5199c398, 0x6787a76a, "....." },
  [51] = { "Ambra dolce", "Porta un Sycamore Branch a Grimbooze Thunderbrew.", "Non ancora filtrato ma appena distillato\n\nCome un campo senza semi, già arato e preparato.\n\nPoi preparerò il nostro mucchio di carbone\n\nPortami un ramo di sicomoro: è la tua prossima missione.", "Il bis? Per te, questo e altro!\n\nNon ancora filtrato ma appena distillato\n\nCome un campo senza semi, già arato e preparato.\n\nPoi preparerò il nostro mucchio di carbone\n\nPortami un ramo di sicomoro: è la tua prossima missione.", "Hic! Oh oh!", 0xcfa75457, 0x4d5230ce, 0x29bc75b2, 0x5a875dd3, 0x6787a76a, "....." },
  [52] = { "Proteggere la frontiera", "Uccidi 8 Prowlers e 5 Young Forest Bears, poi torna da Guard Thomas al ponte orientale di Elwynn.", "Salute, {name}. Più ci si allontana da Goldshire, più gli animali selvatici diventano aggressivi, e l'Eastvale Logging Camp subisce attacchi quasi continui da lupi e orsi!\n\nCi farebbe comodo il tuo aiuto qui.", "Hai ucciso quei lupi e quegli orsi?", "Grazie mille per l'aiuto, {name}. Qualcosa nella foresta deve rendere questi animali così audaci.\n\nQualunque cosa sia, spero che resti lì.", 0x2e116184, 0x03f5e0ac, 0x866a4bcd, 0xfcb3bc90, 0xe7a250d3, "....." },
  [53] = { "Ambra dolce", "Porta a Grimbooze Thunderbrew un fascio di Charred Oak.", "Liquore mellifluo, limpido come il pianto di un bambino\n\nCon gli anni si fa d'ambra, d'un colore sopraffino\n\nMa prima di sbronzarci da capo a piedi, a volontà\n\nUn barile di quercia carbonizzata si costruirà.", "Certo, te la ricanto, amico!\n\nLiquore mellifluo, limpido come il pianto di un bambino\n\nCon gli anni si fa d'ambra, d'un colore sopraffino\n\nMa prima di sbronzarci da capo a piedi, a volontà\n\nUn barile di quercia carbonizzata si costruirà.", "Invecchiato in botte, filtrato nel carbone\n\nTi scende in gola e ti scalda il cuore e la ragione.\n\nBeviamo dunque, un brindisi a te\n\nE a me già che ci siamo, Grimbooze Thunderbrew!", 0xcfa75457, 0x2911d99e, 0x90b69e3d, 0xe5239d0c, 0x5368c39a, "....." },
  [54] = { "Rapporto a Goldshire", "Porta i Marshal McBride's Documents a Marshal Dughan, a Goldshire.", "{name}, come {class} hai dimostrato di avere a cuore la sicurezza di Northshire. Ora ti viene affidata la protezione della Elwynn Forest che la circonda.\n\nSe accetti questo incarico, ho preparato dei documenti da consegnare a Marshal Dughan, a Goldshire. Goldshire si trova lungo la strada a sud, oltre i cancelli di confine.", "Hai notizie da McBride? Northshire è un giardino in confronto alla Elwynn Forest, ma chissà cosa ha da riferire Marshal McBride.\n\nForza, dammi i suoi documenti...", "Bene, qui dice che ti è stato conferito il grado di Acting Deputy presso gli Stormwind Marshals. Congratulazioni.\n\nE buona fortuna: tenere al sicuro Elwynn non è una passeggiata... con quasi tutto l'esercito impegnato a fare chissà cosa per chissà quale nobile!\n\nÈ difficile stare dietro alla politica in questi tempi bui...", 0xccb7dcaf, 0xc0ef425f, 0xd8bc24db, 0xf6530924, 0xb56df9b4, "....." },
  [59] = { "Armature di stoffa e di cuoio", "Consegna lo Stormwind Armor Marker a Sara Timberlain.", "Per la tua astuzia e il tuo valore ho qui un buono che vale un pezzo d'armatura. Portalo a Sara Timberlain, all'Eastvale Logging Camp. Dalle il buono e lei ti forgerà l'armatura. E quando l'avrai, {name}, usala per difendere Elwynn.\n\nL'Eastvale Logging Camp si trova oltre il posto di guardia di Guard Thomas, a est.", "La Stormwind Army mi ha incaricata di fornire alla sua gente armature di stoffa e di cuoio.\n\nSe hai un buono per me, sarò felice di prepararti qualcosa.", "Ah, grazie per il buono. Scegli pure l'armatura che preferisci.\n\nBuona fortuna, prode {class}. E che questa armatura ti serva bene.", 0x751bcd47, 0x88cbb6e2, 0xec149fa7, 0xa0219e98, 0xff5c34aa, "....." },
  [60] = { "Candele dei kobold", "Porta 8 Large Candles a William Pestle, a Goldshire.", "Salve, <messere/madama>! Hai un momento?\n\nIo e mio fratello gestiamo una bottega di speziale a Stormwind, e sono qui a raccogliere Large Candles per la loro cera. Puoi aiutarmi?\n\nLe Large Candles si ottengono dai kobold, e si dice che i kobold stiano infestando le miniere di Elwynn... la Fargodeep Mine a sud e la Jasperlode Mine a est. Ti consiglio di cercare le candele in uno di quei posti.", "Hai già raccolto quelle candele?", "Ti sei <dato/data> da fare a cacciare kobold, eh? Grazie per le candele, {name}: ecco la tua ricompensa...", 0x514933bf, 0xd8ce4567, 0x6cce32c4, 0x77e7ca88, 0x98618684, ".....", nil, nil, 0x1993cf97, nil, nil },
  [61] = { "Una spedizione per Stormwind", "Porta la William's Shipment a Morgan Pestle, nello Stormwind Trade District.", "Mio fratello Morgan aspetta a Stormwind la mia spedizione di candele. Non ho tempo di fare il viaggio di persona, ma se vuoi portargli tu la spedizione, ti pagherà bene.\n\nHo impacchettato le candele: troverai Morgan nella nostra bottega, la Pestle's Apothecary, nello Stormwind Trade District.", "Oh, una spedizione da mio fratello? Splendido! Oggi la fortuna mi sorride davvero!", "Ecco il tuo compenso... e già che sei qui, dai un'occhiata in giro! Di sicuro abbiamo una pozione o un altro gingillo che ti tornerà utile.", 0x6a825135, 0xdeec4138, 0xd71ae934, 0x89b01d8f, 0xdf7db746, "....." },
  [62] = { "La Fargodeep Mine", "Esplora la Fargodeep Mine, poi torna da Marshal Dughan a Goldshire.", "La miniera di Northshire non è l'unica ad avere problemi! Mi riferiscono che anche la Fargodeep Mine, a Elwynn, è diventata un rifugio per i kobold.\n\nEsplora la miniera e conferma queste voci, poi torna da me. La miniera si trova quasi esattamente a sud di Goldshire, tra le fattorie degli Stonefield e dei Maclure.", "Cosa hai da riferire, {name}? Sei <stato/stata> alla Fargodeep Mine?", "Brutte notizie. Cosa ci aspetta ora, i draghi?!? Dovremo aumentare le pattuglie vicino a quella miniera. Grazie per i tuoi sforzi, {name}. E aspetta un momento... forse ho un altro compito per te.", 0x3a373e5c, 0x068c7c5b, 0x196f6d77, 0x620f4981, 0x902000cc, "....." },
  [64] = { "Il cimelio dimenticato", "Farmer Furlbrow vuole che tu recuperi il suo orologio da taschino dall'armadio della sua casa, alla fattoria delle zucche a ovest.", "È stato orribile! Verna mi ha svegliato quando ha sentito un baccano nei campi. I campi erano pieni di teppisti. Siamo scappati di corsa e ho dimenticato di prendere il mio orologio da taschino. Il padre di Verna me lo regalò il giorno del nostro matrimonio, e mi sento male al pensiero che ce l'abbiano quei ladri. L'ho lasciato nell'armadio, in casa. Cerca il campo di zucche a ovest: non puoi sbagliare. Se me lo riporti, te ne sarò davvero grato!", "Non è che sei <riuscito/riuscita> a prendere il mio orologio?", "Il mio orologio! Grazie mille, gentile <signore/signora>!\n\nSiamo solo poveri contadini e abbiamo perso la nostra terra, ma ti prego, accetta questa ricompensa come segno della nostra gratitudine.", 0xf0e121ad, 0xdbaefd0c, 0xf295ad64, 0xc78af9a9, 0x1ca851f8, ".....", nil, nil, nil, nil, 0xd9a3b24b },
  [65] = { "La Defias Brotherhood", "Gryan Stoutmantle vuole che tu parli con Wiley, a Lakeshire.", "La banda di miserabili che ha cacciato la brava gente di Westfall dalle sue terre si fa chiamare The Defias Brotherhood. Ho bisogno che tu ti infiltri in questa combriccola di delinquenti. Dobbiamo sapere chi guida l'organizzazione e dove si nascondono. A Lakeshire, alla locanda, c'è un ladro di nome Wiley che mi deve un favore.\n\nVai a Lakeshire, nelle Redridge Mountains, a est di Elwynn, e scopri quello che puoi.", nil, "Così ti manda Stoutmantle? Be', gli devo un favore.", 0x2a2224c0, 0x5c71d76f, 0x567bbd13, nil, 0xd8800e68, "...m." },
  [66] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [67] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [68] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [69] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [70] = { "La leggenda di Stalvan", "Prendi la Stalvan's Undelivered Letter dal baule e consegnala nel Canal District di Stormwind.", "Il nome Stalvan mi dice qualcosa. Ora ricordo.\n\nMolti anni fa, in una notte di tempesta, arrivò un messaggero in cerca di riparo per la notte. Verso la mezzanotte, l'uomo si precipitò giù per le scale urlando, pallido di paura. Ancora in camicia da notte, sparì sotto l'acquazzone.\n\nNella fretta dimenticò le sue lettere nel baule al piano di sopra, e non tornò mai a riprenderle. Ne è rimasta una di quel tale Stalvan, destinata al Canal District di Stormwind. Prendila pure.", "Cos'hai lì? Fammi dare un'occhiata. . .", "Hai una bella faccia tosta a portare questa roba qui.", 0xeb6571fb, 0xec87b2a9, 0xcf8206e0, 0xad2d2675, 0xf3e822c5, "....." },
  [71] = { "Rapporto a Thomas", "Consegna i Rolf and Malakai's Medallions a Guard Thomas, al ponte orientale di Elwynn.", "Ora che hai entrambi i medaglioni, consegnali a Guard Thomas al ponte, perché sappia che fine hanno fatto le sue guardie assassinate.", "Salve, {name}. Hai scoperto che fine hanno fatto Rolf e Malakai?", "Hai confermato i miei timori, {name}. I murloc sono una minaccia che non possiamo ignorare.", 0xcad5f606, 0xdfec0126, 0xfecbb9ef, 0x8c9b780e, 0xab891fb8, "....." },
  [72] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [74] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [75] = { "La leggenda di Stalvan", "Marshal Haggard vuole che tu cerchi la Faded Journal Page nel baule al piano di sopra.", "Quando mi trasferii qui, nel baule al piano di sopra c'era un fascio di pergamene. Le guardai una volta appena arrivato, ma ci rinunciai quando la nebbia mi annebbiò gli occhi.\n\nFai un favore a un vecchio quasi cieco e guarda nel baule di sopra se c'è qualcosa che possa aiutarti a scoprire di più su questo Stalvan. Sono quasi sicuro che ci sia una pagina di diario sbiadita che potrebbe interessarti. Portamela e ti aiuterò come posso.", "Hai trovato la pagina di cui ti parlavo, {name}?", "L'hai trovata!", 0xeb6571fb, 0x74cb8926, 0x33923181, 0x856913a4, 0x3715d975, "....." },
  [76] = { "La Jasperlode Mine", "Esplora la Jasperlode Mine, poi torna a fare rapporto a Marshal Dughan a Goldshire.", "Grazie a te sappiamo che la Fargodeep Mine è infestata dai kobold. Ora ci serve un esploratore che indaghi sulla Jasperlode Mine, più lontana.\n\nEsplora la Jasperlode e verifica se ci sono kobold. Per raggiungere la miniera, segui la strada verso est fino alla Tower of Azora. Dalla torre vai a nord e troverai la miniera ai piedi delle colline.", "Salute, {name}. Cosa hai da riferire? Hai esplorato la Jasperlode Mine?", "Kobold alla Jasperlode Mine, dici? Maledizione! La situazione peggiora di minuto in minuto!\n\nGrazie per il rapporto, {name}. Ma vorrei che le notizie che mi porti fossero buone.", 0x0323d68b, 0xb489dc45, 0xd63cfe6e, 0x3d82a623, 0xf3bd38e1, "....." },
  [78] = { "La leggenda di Stalvan", "Porta la Faded Journal Page a Tavernkeep Smitts.", "Conosco qualcuno che potrebbe aiutarti. Quando comandavo la Stormwind Guard, andavamo a bere alla Scarlet Raven Tavern, a Darkshire. Il locandiere, Smitts, era un vero esperto delle storie del posto. Mostragli questa pagina e senti cosa ne pensa.", "Ti manda Marshal Haggard? Perché non l'hai detto subito?\n\nAh, il buon vecchio Haggard. Poveretto, tra non molto sarà completamente cieco. Comunque, fammi vedere cos'hai lì.", "Per la Luce! Puoi scommetterci che riconosco questa calligrafia.", 0xeb6571fb, 0x9665adb8, 0xd11badb8, 0x01f28add, 0x017fe17b, "....." },
  [79] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [80] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [83] = { "Merce di lino rosso", "Porta 6 Red Linen Bandanas a Sara Timberlain, all'Eastvale Logging Camp.", "La banda dei Defias a Northshire porta maschere di tela di sacco, ma i Defias di Elwynn indossano il lino, che posso usare per confezionare ottimi capi.\n\nPortami delle Red Linen Bandanas e le userò per farti qualcosa.\n\nI membri della banda dei Defias hanno accampamenti sparsi in tutta Elwynn.", "Sto finendo il lino, {name}. Ne hai per me?", "Ah, sono belle bandane, anche se un po' ruvide...\n\nEcco qua!", 0xab13ee46, 0x6ab947a0, 0x2f31ce58, 0x13c355f0, 0xb808f80e, "....." },
  [84] = { "Ritorno da Billy", "Porta la Pork Belly Pie a Billy Maclure, ai Maclure Vineyards.", "Ecco qua. E quando dai questa torta a quel Billy, digli che spero gli vada di traverso!", "Uff... sto morendo di fame! Hai quella torta per me, {name}?", "Mmm, che buona! Questa torta è la migliore!\n\nMi sa che mi sta tornando la memoria...", 0x77e92707, 0xb3802d9c, 0x8c11f6b5, 0xa7950cc8, 0x90374641, "....." },
  [85] = { "La collana perduta", "Parla con Billy Maclure.", "Ho perso la mia collana, e credo che l'abbia presa quel monello di Billy Maclure! Di solito zampetta come un ratto intorno ai Maclure Vineyards, a est di qui.\n\nRiportami la collana e scalderai il cuore di una vecchia vedova.", nil, "Hai perso cosa? Be', io nessuna collana ho preso, perché non sono mica un ladro!\n\nForse so chi è stato, ma... <sogghigna>... ho troppa fame per ricordarmelo.", 0x1a691c23, 0x3c0d0519, 0xc37d5922, nil, 0xc488cf29, "...m." },
  [86] = { "Una torta per Billy", "Porta 4 Chunks of Boar Meat ad Auntie Bernice Stonefield, alla Stonefield's Farm.", "Forse, se avessi una torta, potrei dirti chi ha quella collana. E sai, credo che quella vecchia Bernice dell'altra fattoria faccia delle ottime Pork Belly Pie...\n\nMagari, se le dai un po' di carne dei cinghiali che girano intorno alle nostre fattorie e le dici a cosa serve, ti cuocerà una torta.", "Non mi sembra giusto sfamare proprio il ragazzo che mi ha rubato la collana, ma se è questo che serve per riavere ciò che è mio, e sia!\n\nHai quella carne di cinghiale?", "Questa carne di cinghiale selvatico è dura, ma se la fai sobbollire abbastanza viene fuori proprio una torta squisita!", 0xe258953a, 0x3d1f7b01, 0xb9e0bfdc, 0xd53bb684, 0x6b1f64bc, "....." },
  [87] = { nil, "Porta la Bernice's Necklace ad \"Auntie\" Bernice Stonefield, alla Stonefield Farm.", "Stavo giocando vicino alla Fargodeep Mine, e credo di aver perso, ehm... cioè, di aver visto la collana della vecchia. Non chiedermi come ci sia finita... non sono stato io!\n\nBe', comunque, ho visto un kobold grosso, con un dente d'oro, raccogliere la collana e scappare nella miniera. Trova quel kobold e troverai la collana, lo giuro!", "Salve, {name}. Hai trovato la mia collana?", "Oh, l'hai trovata! Grazie, grazie, tesoro!\n\nTieni, prendi questo. Era di mio marito, e diceva sempre che portava fortuna. Se solo non l'avesse dimenticato durante la sua ultima campagna! *snif*", nil, 0xec235807, 0x329228f9, 0x511d94a7, 0x9137e39e, "m...." },
  [88] = { "Princess deve morire!", "Uccidi Princess, prendi il suo collare e portalo a Ma Stonefield, alla Stonefield Farm.", "I Brackwell hanno una maiala che ha vinto dei premi, Princess. La scrofa è enorme, ed è diventata così venendo di nascosto qui a mangiarsi le mie verdure!\n\nQuindi, prima che arrivi ai nostri campi... Princess deve morire! Portami il suo collare come prova e ti darò qualcosa per il disturbo!\n\nDi solito Princess sta nella Brackwell Pumpkin Patch, a est, oltre la fattoria dei Maclure. Prendila prima che le venga fame e torni qui!", "L'hai vista? L'hai presa?", "Meno male! Quella maiala stava diventando così grossa che si sarebbe mangiata tutto il raccolto! Grazie, {name}.\n\nAllora, ti va bene una di queste cose?", 0xd0c3b757, 0x87ee4e48, 0xb6b583eb, 0x6ce3847c, 0x8ee1d213, "....." },
  [89] = { "L'Everstill Bridge", "Porta 5 Iron Pikes e 5 Iron Rivets a Foreman Oslow, a Lakeshire.", "Durante l'ultima invasione degli orchi siamo stati costretti a fondere il nostro ferro per farne proiettili, spade e armature. Abbiamo chiesto a Stormwind una nuova spedizione di materiali, ma una banda di gnoll di Redridge ha assaltato la carovana ed è fuggita sulle colline dietro Lakeshire.\n\nOra ci mancano le scorte per ricostruire questo ponte. Se mi porti 5 Iron Pikes e 5 Iron Rivets, {name}, farò in modo che tu venga ricompensato.\n\nOra mettiamoci al lavoro!", "Questo ponte non si costruisce da solo! Allora, dove sono quelle Iron Pikes e quei Iron Rivets?", "Ottimo lavoro, {name}. Questi materiali aiuteranno moltissimo a ricostruire il ponte. Rimetteremo in piedi questa bellezza in un attimo.", 0xfbe560d1, 0x5c73aae5, 0xcb575d10, 0xf3038219, 0xf1b96a47, "....." },
  [91] = { "La legge di Solomon", "Porta 10 Shadowhide Pendants a Bailiff Conacher, nella Lakeshire Town Hall.", "Un nemico di Stormwind si è stabilito sulle colline orientali di Redridge. Questo malvagio usa l'Arcane per seminare terrore e sofferenza nel nostro paese e tra la nostra gente. Porta avanti i suoi affari malvagi con il nome di Morganth.\n\nOra Morganth controlla lo Shadowhide Gnoll Clan, che esegue i suoi ordini. Come stabilisce la Law of Lakeshire, aiutare un criminale del regno si punisce con la morte.\n\nQuesti luridi gnoll vanno uccisi!\n\nConsegnami 10 Shadowhide Pendants e sarai ricompensato.", "Consegnami 10 Shadowhide Pendants e sarai <ricompensato/ricompensata>.", "La Court of Lakeshire riconosce il tuo impegno per la giustizia, {name}. Facendo rispettare le leggi del regno, hai contribuito a difendere la giustizia di queste terre.", 0x4cdcd468, 0x14f882a1, 0xdf5729ff, 0x236bce06, 0x10ddb922, "....." },
  [92] = { nil, "Chef Breanna di Lakeshire vuole 5 pezzi di Tough Condor Meat, 5 Great Goretusk Snouts e 5 porzioni di Crisp Spider Meat.", "Niente mi farebbe più piacere che prepararti un po' di Redridge Goulash. Ma c'è un piccolo problema. Durante la recente rivolta degli orchi ho sfamato l'intera brigata delle truppe di Stormwind. Ora la mia dispensa è vuota. Ma se mi procuri gli ingredienti, sarò felice di accontentarti.\n\nPortami solo 5 pezzi di Tough Condor Meat, 5 Great Goretusk Snouts e 5 porzioni di Crisp Spider Meat.", "Mi servono ancora 5 pezzi di Tough Condor Meat, 5 Great Goretusk Snouts e 5 porzioni di Crisp Spider Meat.", "Ben fatto, {name}. E che begli esemplari! Ed ecco la tua prelibatezza nota come Redridge Goulash!", nil, 0xa292ee13, 0x05480404, 0x61808eeb, 0xd0740ab9, "m...." },
  [94] = { "Un occhio vigile", "Porta il Glyph of Azora alla Lion Statue vicino alla Tower of Ilgalar, a Redridge.", "Il mio rivale, Morganth, è un mago spietato e molto potente che vive nella Tower of Ilgalar, a Redridge. Ho escogitato un modo per spiarlo, l'Eye of Azora, e ora posso osservarlo da lontano.\n\nMa per studiare i suoi pensieri... mi serve altro aiuto.\n\nSe te la senti, porta il mio Glyph of Azora alla Tower of Ilgalar e posalo sulla Lion Statue vicino alla torre.\n\nFatto questo, il potere di Azora mi concederà visioni dei piani futuri di Morganth.", "Questa Lion Statue sta qui da decenni e veglia solitaria sulla famigerata Tower of Ilgalar.\n\nAlla base della statua c'è un incavo, dove si potrebbe incastonare una gemma o un glifo...", "Posi il Glyph of Azora sulla pietra. Aderisce da solo... e ne senti uscire la voce senza corpo di Theocritus:\n\nHai la mia gratitudine, giovane {name}. Ora potrai parlarmi attraverso questo glifo, e forse avrò altri compiti per te... dopo aver sondato i pensieri del mio rivale.", 0x4ce3e4cb, 0xae7ae989, 0x32080b45, 0x5d05e43a, 0x338c1c3b, "....." },
  [97] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [98] = { "La leggenda di Stalvan", nil, nil, nil, nil, 0xeb6571fb, nil, nil, nil, nil, ".mmmm" },
  [102] = { "Pattuglia a Westfall", "Porta 8 Gnoll Paws a Captain Danuvin, a Sentinel Hill.", "Stormwind ci ha abbandonati. Un vento malsano di depravazione soffia sulle pianure di Westfall. Questa era la mia terra, e non volterò le spalle ai cittadini che scelgono di restare. Noi, gli ex contadini, terremo duro.\n\nIl tuo compito, se decidi di accettarlo, è pattugliare le praterie di Westfall. Rintraccia e uccidi i luridi gnoll che sembrano lavorare d'accordo con i ladri delle Deadmines. Portami 8 Gnoll Paws e ricompenserò il tuo coraggio.", "Hai già raccolto 8 zampe da quei gnoll traditori?", "Ben fatto, {name}. Con avventurieri valorosi come te a combattere al fianco della People's Militia, Westfall potrebbe tornare a essere il granaio prospero di un tempo. Ti prego, accetta questo in riconoscimento dei tuoi sforzi instancabili.", 0xbdbd8c1d, 0xb285aa6c, 0x08d3c8d8, 0x34967c23, 0xe6d9e3f6, "....." },
  [103] = { "Custode della fiamma", "Porta 5 Flasks of Oil a Captain Grayson, al Westfall Lighthouse.", "La notte in cui morì la famiglia del guardiano del faro fu orribile. Guardai, impotente, mentre Old Murk-Eye guidava l'attacco. Ma ciò che è fatto è fatto, e ora mi preoccupo per la vita dei marinai del Great Sea, le cui navi si avvicinano agli scogli insidiosi della costa. Senza nessuno a vegliare sulla fiamma, la responsabilità è ricaduta su di me.\n\nAiutami a tenere accesa la torcia portandomi 5 Flasks of Oil dagli Harvest Monsters.", "La fiamma non brucerà a lungo senza olio, {name}.", "Che tu sia lodato, prode {class}. Grazie al tuo duro lavoro, gli scogli della Westfall Coast saranno illuminati. Molte vite saranno risparmiate finché la torcia resterà accesa.\n\nIo morii inutilmente su questa stessa riva. Il mio compito nell'aldilà è fare in modo che nessun altro segua il mio destino.", 0x3ef7ad7a, 0xadaf38bb, 0x2c40ca7a, 0xd537b66e, 0x38ec3914, "....." },
  [104] = { "La minaccia della costa", "Porta una scaglia di Old Murk-Eye a Captain Grayson, al Westfall Lighthouse.", "Quando la mia vita finì su quegli scogli, non avevo idea di cosa mi riservasse l'aldilà. Quella notte il Lighthouse era buio, perché Old Murk-Eye aveva fatto fuggire la famiglia del guardiano. Tornarono e riaccesero la fiamma, ma Old Murk-Eye costrinse i murloc più deboli di mente ad assaltare di nuovo il Lighthouse con lui. La seconda volta la famiglia non fu così fortunata, e morirono impotenti davanti ai miei occhi.\n\nUccidi Old Murk-Eye se lo vedi lungo la riva, portami una delle sue scaglie e ti ricompenserò.", "Hai già annientato la minaccia nota come Old Murk-Eye? È stato visto aggirarsi lungo la costa di Westfall.\n\nTorna da me quando quella lurida bestia sarà morta.", "Dunque il lurido pagano, Murk-Eye, è morto. Ben fatto, {name}. Per mano tua una vita è stata spenta, ma forse molte altre sono state salvate. Il Great Sea, pieno di pericoli com'è, stanotte sarà un pochino più sicuro grazie al tuo eroismo.", 0x2f06382c, 0x9bc7f6db, 0xa6201dcb, 0xd389c8ba, 0xf95015fd, "....." },
  [106] = { "Giovani innamorati", "Consegna la Maybell's Love Letter a Tommy Joe Stonefield.", "Oh, sono maledetta! Il mio cuore appartiene a Tommy Joe Stonefield, ma le nostre famiglie sono nemiche giurate. Così non posso vederlo, anche se i miei occhi bramano di guardare quel bel viso!\n\nTi prego, prendi questa lettera e dalla a Tommy Joe. Di solito è al fiume a ovest della Stonefield Farm, che si trova proprio a ovest di qui.", "Hai cosa?? Maybell è la luce della mia vita grigia. Presto, fammi vedere la sua lettera!", "Ah! Non sopporto di stare lontano da lei. Devo vederla!!", 0x39bb27e6, 0xaca204cb, 0x455a69fe, 0x8ed56116, 0xaef57c73, "....." },
  [107] = { "Un biglietto per William", "Porta la Gramma Stonefield's Note a William Pestle.", "Scommetto che William Pestle ha una pozione per unire i nostri due giovani innamorati!\n\nTieni, porta questo biglietto a William. Alloggia al Lion's Pride Inn, a Goldshire.", "Hai un biglietto da \"Gramma\" Stonefield, eh? Non vedo Mildred da anni! Chissà cosa ha da dire...", "Il mio cuore soffre per quelle due povere anime, Maybell e Tommy Joe. Ricordo cosa vuol dire essere giovani e innamorati, un tempo.\n\nCi dev'essere qualcosa che posso fare per aiutarli! Fammi pensare...", 0x94227104, 0x6cf2cbc4, 0x613551b1, 0x4d3b404b, 0xd5a99e73, "....." },
  [109] = { "Rapporto a Gryan Stoutmantle", "Parla con Gryan Stoutmantle. Di solito si trova nella torre di pietra di Sentinel Hill, appena fuori dalla strada, nel mezzo di Westfall.", "Mi pare che tu abbia visto parecchie battaglie, {class}. Se non l'hai già fatto, dovresti andare a fare rapporto a Gryan Stoutmantle. È a capo della People's Militia, che protegge i campi di Westfall. Scommetto che il tuo aiuto gli farebbe comodo. Di solito lo trovi nella torre di pietra di Sentinel Hill, appena fuori dalla strada, nel mezzo di Westfall.", nil, "Ah, quindi ti manda il mio amico? Che gentile.\n\nBe', la Stormwind Monarchy ha abbandonato la nostra causa. Ora tocca alla People's Militia tenere queste terre libere dalla corruzione. Se la nostra causa ti interessa, posso mettere a frutto le tue doti di combattimento in nome della libertà.", 0xc82e5075, 0x03f579cf, 0x50233a5c, nil, 0xb444ea08, "...m." },
  [111] = { "Parlare con Gramma", "Parla con Gramma Stonefield.", "Ti prego, {name}, parla con la mia Gramma. Se c'è qualcuno che può trovare il modo di farmi stare con Maybell, è lei.\n\nÈ in casa nostra, a est di qui.", "Non vedo l'ora di sapere come reagiranno i miei amici!\n\nNon se lo aspetteranno mai", "Finché le nostre famiglie sono in lite, Tommy Joe e Maybell non hanno un gran futuro, ma... forse possiamo farli stare insieme almeno per un po'.\n\nMmm, cosa possiamo fare...", 0x6b3f9d7c, 0xf51e0819, 0x90033b93, 0x96b93e46, 0x2fa7cabf, "....." },
  [112] = { "Raccolta di alghe", "Porta 4 Crystal Kelp Fronds a William Pestle, a Goldshire.", "Posso preparare per Maybell un Invisibility Liquor, così potrà sgattaiolare via dai Maclure Vineyards e raggiungere Tommy Joe. Ma per fare il liquore mi serve dell'alga cristallina.\n\nDi solito l'alga cresce nell'oceano... ma a volte i murloc la raccolgono. Vedi se i murloc vicino al Crystal Lake ne hanno. Il Crystal Lake è appena a est di Goldshire.", "Hai quell'alga cristallina? Di sicuro Maybell non vede l'ora di vedere il suo innamorato...", "Le hai prese. Ben fatto! Ora un momento solo, mentre preparo la pozione...", 0x2bebb48c, 0x3fc93ac6, 0x9e5c1b2e, 0x73f21124, 0xca7123ec, "....." },
  [114] = { "La fuga", "Porta l'Invisibility Liquor a Maybell Maclure.", "Porta questo Invisibility Liquor alla giovane Maybell. Dovrebbe durare abbastanza perché possa far visita a Tommy Joe.", "Hai consegnato la mia lettera a Tommy Joe? Cosa ha detto??", "Oh... cielo! Mi sento in colpa a ingannare la mia famiglia, ma ciò che provo per Tommy Joe è troppo forte per ignorarlo.\n\nGrazie, {name}. Berrò questo liquore appena potrò e sgattaiolerò via dal mio amore.\n\nE per te... ti prego, prendi questo.", 0x437cedda, 0x7b2f4392, 0x62549b36, 0x692ffc74, 0xe0cf61c2, "....." },
  [115] = { "Magia delle ombre", "Porta 3 Midnight Orbs a Marshal Marris, a Lakeshire.", "Gli orchi Blackrock hanno arruolato degli shadowcaster per aiutarli negli attacchi a Redridge, e hanno portato con sé strumenti di potere oscuro: le Midnight Orbs. Queste sfere hanno inferto colpi pesanti ai difensori di Redridge, ed è indispensabile togliere di mezzo questi oggetti contaminati dai demoni.\n\nTrova le Midnight Orbs sugli shadowcaster Blackrock uccisi e portamele. Poi le farò distruggere, perché questo mondo sarebbe un posto migliore senza di esse!", "Come va la lotta con gli shadowcaster? Hai trovato le Midnight Orbs?", "Grazie, {name}. Le manderò subito a distruggere.", 0x904fce2a, 0x60db0353, 0x5b872785, 0x92dca9d4, 0x6e8c3d71, "....." },
  [116] = { "Tempi di siccità", "A Barkeep Daniels di Lakeshire servono un barile di Thunderbrew Lager, una botticella di Merlot, una bottiglia di Moonshine e un otre di Sweet Rum.", "Mi trovo in un bel guaio, {name}. Le bottiglie sono quasi vuote. L'ultima spedizione di liquori è in ritardo da un pezzo. L'invasione degli orchi è stata un inferno.\n\nForse potresti lavorare per me?\n\nMi serve che tu vada a prendere un barile di Thunderbrew Lager da Grimbooze Thunderbrew, sulle colline di Westfall, una botticella di Merlot a Stormwind, una bottiglia di Moonshine a Darkshire e un otre di Sweet Rum a Goldshire. Portameli e farò in modo che tu sia <ricompensato/ricompensata>.", "Mi serve che tu vada a prendere un barile di Thunderbrew Lager da Grimbooze Thunderbrew, sulle colline di Westfall, una botticella di Merlot a Stormwind, una bottiglia di Moonshine a Darkshire e un otre di Sweet Rum a Goldshire. Portameli e farò in modo che tu sia <ricompensato/ricompensata>.", "Un lavoro ben fatto, {name}! Conosco bene le strade che hai dovuto percorrere per procurarti questa bella scelta di liquori. Ma i miei clienti torneranno felici!\n\nMia moglie è una sarta piuttosto brava. Ti prego, accetta questo mantello che ha fatto lei, in cambio dei tuoi servigi.", 0x1c0c7a25, 0x8d7bd5b0, 0xd5a46db2, 0x61956f46, 0xbe7fa4ea, "....." },
  [117] = { nil, "Porta 5 luppoli a Grimbooze Thunderbrew per completare la sua birra speciale.", "Presto, amico mio, sbrigati e corri\n\nSe vuoi una lager che non sappia d'orzo e porri\n\nChe sappia di birra e non di stufato,\n\nServe il luppolo per il nostro preparato.", "Presto, amico mio, sbrigati e corri\n\nSe vuoi una lager che non sappia d'orzo e porri\n\nChe sappia di birra e non di stufato,\n\nServe il luppolo per il nostro preparato.", "Luppolo e orzo, lievito e malto\n\nIl palato subisce un vero assalto,\n\nNon serve implorare, non serve pregare\n\nLa Thunderbrew Lager in barile la puoi trovare!", nil, 0xcca1a58d, 0xf52ffef7, 0xf52ffef7, 0xed1e1cbe, "m...." },
  [118] = { "Il prezzo dei ferri", "Porta la Verner's Note a Smith Argus, a Goldshire.", "Ho usato così tanto ferro per equipaggiare le Stormwind Guards che non me ne resta abbastanza per ferrare i cavalli della stalla!\n\nPorta questo biglietto a Blacksmith Argus, a Goldshire. Gli spiega il mio problema e gli chiede una spedizione di ferri di cavallo.", "Cos'è? Ti manda Verner, dici? Be', dammi il suo biglietto. E parla più forte!", "Eh, così il vecchio Verner ha bisogno di ferri, eh!?!", 0x0dd0b1f0, 0x58b93226, 0xff4bd583, 0xf790dafa, 0x3e4e8e76, "....." },
  [119] = { "Ritorno da Verner", "Torna da Verner Osgood a Redridge e consegnagli la Crate of Horseshoes.", "Va bene, gli darò i suoi 50 ferri di cavallo...\n\nEccoli qui, tutti inscatolati e pronti a partire! Di' a Verner che è stato un piacere fare affari con lui, e assicurati che legga il biglietto attaccato a questa cassa!", "Bene, sei <tornato/tornata>! Hai preso i ferri?", "Grazie, questo mi aiuta davvero.\n\nMa cos'è questo? Argus ha mandato un biglietto con la cassa... Cosa?? Argus vuole che sia io a pagarlo? Bah!\n\nBe', {name}, grazie per l'aiuto.", 0x1296097e, 0x49433401, 0xe1ab4783, 0xa467f765, 0x16236c6c, "....." },
  [120] = { "Un messaggero per Stormwind", "Magistrate Solomon ti ha dato un rapporto da consegnare al General Marcus Jonathan, a Stormwind. Il giudice vuole che tu torni da lui appena fatta la consegna.", "Sono tempi difficili, {class}. La municipalità è sotto assedio continuo. Senza rinforzi andremo sicuramente incontro alla sconfitta. Il messaggio che ora ti affido è della massima importanza. Porta subito questo rapporto al General Marcus Jonathan di Stormwind. Fatta la consegna, torna immediatamente da me con qualunque notizia, buona o cattiva.\n\nOra sbrigati!", "Cos'hai lì?", "Riposo, {class}.\n\nMagistrate Solomon è un capo nobile. Le sue parole hanno molto peso per me. Chiederò consiglio al re e gli spiegherò chiaramente la situazione. Assicura al buon giudice che ha il sostegno della Stormwind Army. I rinforzi saranno inviati appena Sua Maestà darà l'ordine.", 0x7fd00169, 0xf2be5934, 0x06176f7a, 0x19bf3607, 0x6d2fb894, "....." },
  [121] = { "Un messaggero per Stormwind", nil, nil, nil, nil, 0x7fd00169, nil, nil, nil, nil, ".mmmm" },
  [122] = { "Scaglie del ventre", "Raccogli 6 Underbelly Whelp Scales dai Black Dragon Whelps e portale a Verner Osgood, a Redridge.", "Mi servono delle scaglie del ventre dei draghetti neri per pagare i ferri che Argus mi ha mandato da Goldshire. Se me ne porti 6, potrò pagare Argus con una parte... e avanzarne abbastanza per farti qualcosa.\n\nI draghetti neri volano spesso a sud di Lakeshire, ma amano spostarsi. Forse dovrai solo tenere gli occhi aperti e cacciarli quando li vedi.", "So che quell'avido di Argus manderà qualcuno a prendersi le scaglie se non gliele do presto. Hai già trovato quelle scaglie?", "Grazie! Con queste mi libero del debito con Argus...", 0x068001c9, 0xd4d12cd6, 0xcda5c273, 0xef1640b6, 0xf521558d, "....." },
  [123] = { nil, "Vai da Marshal Dughan a Goldshire e consegnagli The Collector's Schedule", "Questo foglio è un calendario con un elenco di giorni e orari in cui una persona, descritta solo come \"The Collector\", riceverà una spedizione d'oro dalle miniere della Elwynn Forest.\n\nDal calendario sembra che il Collector si nasconda vicino alla Brackwell Pumpkin Patch, nella parte orientale di Elwynn.\n\nSembra una cosa importante. Dovresti riferirla a Marshal Dughan, a Goldshire.", "Cosa?!? Sono mesi che non abbiamo gente al lavoro nelle miniere di Elwynn!\n\nFammi vedere quel biglietto che hai...", "Mmm... ho sentito parlare di questo \"Collector\", ma non so per chi lavori. Grazie per il calendario. Ci aiuterà a risolvere il mistero.", nil, 0x3b835957, 0x5a3d01e4, 0xb33d4341, 0x318a1e2f, "m...." },
  [124] = { "Gnoll che ululano", "Uccidi 10 Redridge Brutes e 8 Redridge Mystics, poi torna da Verner Osgood.", "Come se gli orchi all'attacco non bastassero! Ora ho anche bruti e mistici gnoll che si aggirano sulla cresta a nord della mia stalla e mi prendono i cavalli quando si allontanano...\n\nSe riesci a liberarti di quegli gnoll, io e i miei cavalli te ne saremo molto grati.", "I miei cavalli sono ancora nervosi, e la notte sento ancora quel maledetto ululato. Ti prego, {name}, fai qualcosa per quegli gnoll!", "Grazie per tutto il tuo aiuto, {name}.", 0xe85ed098, 0xa4d31ccd, 0xaddbfb20, 0x1ef3dbfd, 0xac71f116, "....." },
  [125] = { "Gli attrezzi perduti", "Foreman Oslow di Lakeshire vuole che tu recuperi la sua cassetta degli attrezzi dal fondo del Lake Everstill.", "Mi servirebbe proprio una mano, {name}. Con il paese sotto assedio è stato difficile ricevere rifornimenti. I miei attrezzi arrivavano da Goldshire su un carro, ma il ponte è saltato. Abbiamo messo gli attrezzi su una barca, ma gli orchi l'hanno colpita con una catapulta. Che sfortuna: la mia cassetta degli attrezzi è finita dritta sul fondo del lago.\n\nRecupera la mia cassetta, {name}, e ne varrà la pena.", "Sei <riuscito/riuscita> a trovare i miei attrezzi?", "Ottimo recupero, {name}! Non pensavo che avrei rivisto questi attrezzi.", 0xc690e293, 0xe17d01d0, 0x00f67f4e, 0xc0af6727, 0xa3088c9c, "....." },
  [126] = { "Ululati tra le colline", "Porta la Yowler's Paw a Verner Osgood, a Lakeshire.", "{name}, gli gnoll sono ancora là fuori. Sento i loro latrati mentre cacciano sulle colline sopra Lakeshire. E un grido è più forte degli altri: Yowler, il loro capo.\n\nUccidi Yowler e disperdi il suo branco! Portami la sua zampa come prova.\n\nE stai <attento/attenta>: se questo gnoll è il loro capo, c'è un motivo. Non è un Mongrel qualunque...", "Yowler è una creatura pericolosa, {name}. Se non sei <pronto/pronta> ad affrontarlo, lo capisco.", "Grazie ancora per l'aiuto. La Stormwind army è così occupata con gli orchi che non ha truppe per proteggere Redridge dalle minacce locali come gli gnoll.", 0x8dfeeed2, 0x12e4af10, 0x3fd1157a, 0x33d0330f, 0x3ba08361, "....." },
  [127] = { "Pesce in vendita", "Porta 10 Spotted Sunfish a Dockmaster Baren, a Lakeshire.", "Il Lake Everstill è famoso per i suoi Spotted Sunfish. C'è sempre richiesta... e io ne ho pochi!\n\nPortamene un carico di 10 e ti farò un buon prezzo. Se non sai pescare, allora... magari puoi prenderli ai murloc!", "Hai qualche sunfish per me, eh?", "Un piacere fare affari con te, compare!", 0x8959426d, 0x299dd9a7, 0x595008a9, 0x1c00230f, 0x0c2062ce, "....." },
  [128] = { "Taglia sui Blackrock", "Uccidi 15 Blackrock Champions e Guard Howe, a Lakeshire, ti ricompenserà.", "Il Blackrock Clan va distrutto. Il nemico ha invaso le nostre terre. Queste montagne sono sotto il diritto sovrano del re di Stormwind. Le nostre fonti dicono che i capi di ogni unità del clan sono chiamati Champions. Li troverai nel loro accampamento a nord, appena a ovest della strada per le Burning Steppes.\n\nMagistrate Solomon vuole questi luridi bruti morti. Uccidi 15 Blackrock Champions e torna da me.", "Torna quando avrai ucciso 15 Blackrock Champions.", "Vedo che hai combattuto con valore contro il Blackrock Clan, {class}. Il tuo servizio alla nostra municipalità è davvero grande.", 0xccdac34a, 0x3dc788d9, 0x3c6954d1, 0x465f09c0, 0x3ae1dc90, "....." },
  [129] = { "Un pranzo gratis", "Porta il pranzo di Parker a Guard Parker. Pattuglia la strada che porta a Darkshire.", "Mi faresti un favore? Ho preparato il pranzo per Guard Parker, ma è fuori di pattuglia... è una guardia di Stormwind grande e forte che sa difendersi, ma là fuori è troppo pericoloso per una paesana come me.\n\nQuindi, se gli porti il pranzo al posto mio, poi torna qui e ti darò un pranzo gratis! Parker pattuglia il tratto di strada che porta a Duskwood.", "Darcy mi ha mandato il pranzo, eh? Che cuore gentile che ha. Be'... dammelo!", "Grazie, un pasto mi ci voleva proprio. Difendere Lakeshire dagli orchi e dagli gnoll è un lavoro duro!", 0x88d7e35c, 0xaad7a98b, 0x9db66007, 0x3d1d5d66, 0xe1a276a1, "....." },
  [130] = { "Visita all'erborista", "Parla con l'erborista di Redridge, Martie Jainrose.", "Prima di tornare da Darcy, puoi portarle dei fiori da parte mia? Li trovi alla bottega dell'erborista a Lakeshire, in fondo al paese, a ovest.\n\nMa quando prendi i fiori... non dire all'erborista, Martie, da parte di chi sono né per chi sono...", nil, "Ti serve un mazzo di fiori? Non sei in paese da molto... hai già trovato qualcuno che ti piace?\n\nSo che non dovrei impicciarmi, ma è bello vedere che c'è amore nell'aria... soprattutto in tempi pericolosi come questi.", 0x71fe59f9, 0xa1ba4f91, 0x49da55c6, nil, 0x081a325e, "...m." },
  [131] = { "Consegna di narcisi", "Consegna a Darcy il Daffodil Bouquet.", "Ecco il tuo mazzo di fiori. Ti ho scelto dei narcisi. Sono i miei preferiti!", "Eccoti di nuovo, {name}. A Parker è piaciuto il pranzo che gli ho mandato?", "Oh, sono bellissimi! Non vedo l'ora di metterli nell'acqua!\n\nMa... questi sono i fiori preferiti di Martie. Parker non ti avrà mandato da quella gelosa di una volpe per questo mazzo, vero? Non le hai detto per chi erano, vero? Se l'hai fatto, non mi stupirebbe se li avesse avvelenati.\n\nOh, ma non è colpa tua. Grazie, ed ecco il tuo pasto.", 0xf4e8832d, 0x70089ffd, 0x81de289a, 0xa471da13, 0x046112fa, "....." },
  [132] = { "La Defias Brotherhood", nil, nil, nil, nil, 0x2a2224c0, nil, nil, nil, nil, ".mmmm" },
  [135] = { "La Defias Brotherhood", "Porta la Wiley's Note a Mathias Shaw, a Stormwind.", "Mi chiedo cosa intendesse Wiley quando ha parlato degli Stonemasons. Forse gli è scappato. Possibile che la banda dei Defias abbia a che fare con gli Stonemasons? Solo un uomo potrebbe saperlo con certezza: Mathias Shaw, capo dello SI:7. Mostragli la Wiley's Note e senti se ha qualcosa da aggiungere a questo mistero sempre più fitto. Se hai difficoltà a trovare Shaw, cerca nelle Barracks della Old Town.", "Che affari hai con me? Sono un uomo molto impegnato. . .", "La faccenda potrebbe essere più complicata di quanto Stoutmantle immagini.", 0x2a2224c0, 0x95f26f8f, 0x0882b814, 0x12eeb2a7, 0x48d02edd, "....." },
  [136] = { "Il tesoro nascosto di Captain Sander", "Trova il baule di Captain Sanders e frugaci dentro per il prossimo indizio.", "Se stai leggendo questo, vuol dire che il vecchio Captain Sanders riposa in una tomba d'acqua. Quindi il mio tesoro ora è tuo, devi solo seguire gli indizi.\n\nPrima devi trovare il mio baule. A quest'ora sarà mezzo sepolto nella sabbia, lungo la Western Coast di Westfall, vicino al relitto. Di relitti ce ne sono tanti, ma sulla costa c'è una sola ancora arrugginita. Trova l'ancora e troverai il mio baule! Guarda lì dentro per il prossimo indizio.", nil, "Il baule si apre lentamente, cigolando. Sembra contenere solo sabbia e acqua. Ma aspetta! Ne esce di corsa un granchietto con un indizio per il tesoro tra le chele!", 0x06bba426, 0x0a7c4cb3, 0xa2d6009c, nil, 0x386945df, "...m." },
  [138] = { "Il tesoro nascosto di Captain Sander", "Trova il vecchio barile vicino al camino in rovina e frugaci dentro per il prossimo indizio.", "L'indizio per il tesoro dice: Bel lavoro, compare! Ora devi andare dritto a est. A est su per le scogliere, a est fino alla strada. Cerca le rovine del vecchio camino al lato della strada. Lì troverai un vecchio barile con il prossimo indizio.", nil, "Bel lavoro, <cacciatore/cacciatrice> di tesori!", 0x06bba426, 0x1440041d, 0xf26acf24, nil, 0x7ca63b45, "...m." },
  [139] = { "Il tesoro nascosto di Captain Sander", "Fruga nella brocca vuota accanto al mulino per il prossimo indizio.", "Frugando nel barile scopri un altro pezzo di pergamena. Questo dice: Ora, da questo barile, girati verso nord. Dritto come vola il corvo, continua a camminare finché non vedi la brocca vuota accanto al mulino solitario sulle scogliere. Se frughi intorno a quella brocca, potresti trovare proprio quello che cerchi.", nil, "Sei sulla strada del bottino, <cercatore/cercatrice> di tesori!", 0x06bba426, 0x7ab5b5af, 0x0b996e82, nil, 0xd8473e97, "...m." },
  [140] = { "Il tesoro nascosto di Captain Sander", "Trova il forziere di Captain Sanders e aprilo per avere la tua ricompensa.", "Ed ecco che, in fondo alla Old Jug, c'è un altro indizio per il tesoro di Sander. In qualche punto l'inchiostro è colato e la carta sa di whisky, ma riesci a leggere parte del testo: Ora che hai trovato la mia vecchia brocca di whisky, sei quasi al tesoro! Girati verso ovest dalla bottiglia e scendi fino alla riva. Una volta in acqua, continua! Nuota dritto verso ovest finché non trovi l'isola con il mio forziere!", nil, "I cardini del vecchio forziere sono arrugginiti, ma funzionano ancora. Forzi il forziere e prendi il bottino.\n\nCongratulazioni!", 0x06bba426, 0x01f557fa, 0xc7539c95, nil, 0x6ef48c97, "...m." },
  [141] = { "La Defias Brotherhood", nil, nil, nil, nil, 0x2a2224c0, nil, nil, nil, nil, ".mmmm" },
  [142] = { "La Defias Brotherhood", "Rintraccia il Defias Messenger a Westfall e porta il suo messaggio a Stoutmantle.", "Dobbiamo scoprire dov'è il nascondiglio dei Defias. {name}, il mio esploratore riferisce che un Defias Messenger è stato visto sulle strade tra Moonbrook, la Gold Coast Quarry e la Jangolode Mine. Voglio che tu lo catturi. Se oppone resistenza, uccidilo e portami qualunque cosa abbia con sé.", "{name}, sei <riuscito/riuscita> a raccogliere qualche informazione? Hai trovato il messaggero?", "Questa è davvero la prova certa che a comandare è VanCleef. Ora ci resta solo da sapere dove si nasconde la banda dei Defias.\n\nMentre eri via abbiamo avuto un colpo di fortuna. Abbiamo catturato un ladro che cercava di rubare il carro di Saldean. Ha promesso di guidarci al nascondiglio in cambio della vita. Voglio che tu difenda il traditore, perché possa rivelarci il nascondiglio. Torna da me quando avrai scoperto dove si trova.", 0x2a2224c0, 0x243342aa, 0xf31363c7, 0x484fe496, 0xf9189f7b, "....." },
  [143] = { "Un messaggero per Westfall", nil, nil, nil, nil, 0xf6c85306, nil, nil, nil, nil, ".mmmm" },
  [144] = { "Un messaggero per Westfall", "Torna da Magistrate Solomon con la risposta di Gryan Stoutmantle.", "Leggere il biglietto di Magistrate Solomon mi addolora. Ma è chiaro che non conosce la guerra che si combatte a Westfall, altrimenti saprebbe di non doversi aspettare aiuto dalla Militia. Se anche Stormwind non ci avesse abbandonati, non avremmo bisogno della Militia.\n\nPorta questa risposta al tuo padrone a Redridge, {class}. E digli che il mio cuore è pesante per la perdita di brava gente.", "Possiamo aspettarci presto la People's Militia? Le notizie di Lord Stoutmantle sono buone?", "Devo dire che non va affatto bene. Non sapevo che la situazione di Stoutmantle fosse così simile alla nostra qui a Lakeshire. Quale azione è così importante da allontanare la Stormwind Army dalla sua gente? Bah, non dovrei pensare ad alta voce.\n\nEcco, messaggero. Accetta queste monete in cambio del tuo servizio alla municipalità. Potrei avere ancora bisogno di te.", 0xf6c85306, 0x82d09720, 0x39c0aa3b, 0x16225e09, 0x7726c3a3, "....." },
  [145] = { "Un messaggero per Darkshire", "Magistrate Solomon vuole che tu porti una lettera a Lord Ebonlocke, a Darkshire.", "Ho di nuovo bisogno del tuo aiuto. Ho scritto a Lord Ebonlocke, chiedendogli di mandare le sue guardie addestrate, la Night Watch, ad aiutare a difendere Lakeshire. È indispensabile che questo messaggio gli arrivi in fretta. Devi essere estremamente prudente. Ebonlocke è il sindaco di Darkshire, nel cuore di Duskwood. Non lasciare le strade.", "Sembri venire da lontano, {class}. Che affari hai qui a Darkshire?", "Grazie per aver fatto il lungo viaggio fin qui. Sono davvero informazioni importanti.", 0x74e46a13, 0xbe30acba, 0x0448bdaa, 0x1745350a, 0x089c2d62, "....." },
  [146] = { "Un messaggero per Darkshire", nil, nil, nil, nil, 0x74e46a13, nil, nil, nil, nil, ".mmmm" },
  [147] = { "Caccia all'uomo", "Trova e uccidi \"the Collector\", poi torna da Marshal Dughan con The Collector's Ring.", "Se il \"Collector\" prende l'oro dalle nostre miniere, allora sta derubando il regno! Consegna il Collector alla giustizia e portami l'anello citato nel calendario dei ritiri che mi hai dato. Potrebbe dirci per chi lavora il Collector...\n\nSecondo quel Pickup Schedule, il Collector si nasconde alla Brackwell Pumpkin Patch. Dovresti cercarlo lì.", "Hai trovato il Collector? Hai scoperto per chi lavora?", "L'hai trovato? Ben fatto, {name}. Non \"collezionerà\" più niente dalle Elwynn Mines!\n\nE questo anello che hai trovato è interessante... è un anello di appartenenza alla vecchia Stonemason's Guild di Stormwind. Perché un ladruncolo dovrebbe avere l'anello di una gilda di artigiani, e perché i Defias Thieves raccolgono denaro dalle nostre miniere?\n\nDomande difficili. Spero che un giorno avremo delle risposte.", 0x3fd32b4a, 0xaffbf97d, 0xcaee2d0b, 0x03263e82, 0xe881e64e, "....." },
  [150] = { "Murloc bracconieri", "Porta 8 Murloc Fins a Dockmaster Baren, a Lakeshire.", "I murloc stanno diventando un problema. Gruppi sempre più grandi di uomini-pesce gettano l'ancora lungo le rive del Lake Everstill e pescano a più non posso! Dobbiamo farli sparire prima che si mangino tutto il pesce del lago!\n\nDai la caccia ai murloc! Portami 8 delle loro pinne e forse avrò qualcosa per te...", "Hai quelle pinne? Presto, dobbiamo cacciare quei murloc dal lago!", "Ben fatto, {name}. Spero che quei murloc non ti abbiano dato troppi problemi.\n\nÈ strano vederli così lontano dal mare. Mi chiedo se siano qui perché stanno scappando da qualcosa...", 0x812e47f7, 0xbe5f0814, 0xc927bcbc, 0xabeb396e, 0x9a51f356, "....." },
  [151] = { "Povera Old Blanchy", "Verna Furlbrow, a Westfall, vuole che tu le porti 8 Handfuls of Oats.", "Povera Old Blanchy! È così stanca, dopo tutto il lavoro che le abbiamo fatto fare. Le ho dato da mangiare prima di lasciare la fattoria, ma non ci aspettavamo che il carro si rompesse. Se potessi portarle qualche manciata di avena dai campi, te ne sarei grata.\n\nScommetto che ne trovi intorno a tutte le fattorie di Westfall, se riesci a stare alla larga da quelle macchine orribili che le hanno occupate. Ci sono diverse fattorie a sud-ovest di qui.", "Old Blanchy è allo stremo. Per caso hai trovato dell'avena per lei?", "Grazie mille, {name}! La povera Old Blanchy sarà così felice!", 0x9bfac4dc, 0x7daa1244, 0x1fc2eef2, 0xfc0646d0, 0x51216ba8, "....." },
  [152] = { "La costa non è sgombra", "Uccidi 7 Tidehunters, 7 Warriors, 7 Oracles e 7 Coastrunners e torna da Captain Grayson al Westfall Lighthouse.", "Avrai notato tutti i relitti lungo la costa. Il Great Sea è davvero infido. La costa di Westfall va tenuta sgombra, perché i marinai che arrivano sulle nostre spiagge siano al sicuro. Però i murloc sono un problema.\n\nUccidi 7 Tidehunters, 7 Warriors, 7 Oracles e 7 Coastrunners e farò in modo che tu sia <ricompensato/ricompensata>.", "Uccidi 7 Tidehunters, 7 Warriors, 7 Oracles e 7 Coastrunners e farò in modo che tu sia <ricompensato/ricompensata>.", "Ben fatto, {name}. Hai un bel talento per il combattimento. Grazie a te la costa di Westfall è un posto più sicuro.", 0xcdad2308, 0x88ca96a9, 0xbc9bf3cb, 0xf2f2deb7, 0x27f90f2d, "....." },
  [153] = { nil, "Porta 15 Red Leather Bandanas a Scout Galiaan, a Sentinel Hill.", "Il fronte dei Defias si sposta di continuo. È da parecchio che seguo i loro movimenti. Tra l'altro, ho appurato che molti membri della banda si riconoscono dalle Red Leather Bandanas che portano.\n\nPortami 15 di queste bandane e farò in modo che tu sia <ricompensato/ricompensata>.", "Portami 15 Red Leather Bandanas e ti pagherò bene.", "Bel lavoro, {race}. Ti prego, accetta uno di questi oggetti come paga per tutto il tuo impegno.", nil, 0x15be8c76, 0xdc4ad0de, 0xca1a09c5, 0x9ab69279, "m...." },
  [155] = { "La Defias Brotherhood", "Scorta il Defias Traitor fino al nascondiglio segreto della Defias Brotherhood. Quando il Defias Traitor ti avrà mostrato dove si nascondono VanCleef e i suoi uomini, torna da Gryan Stoutmantle con l'informazione.", "Così Stoutmantle manda te, {race} pelle e ossa, a proteggermi? Mi sa che dovrò accontentarmi. Meglio se porti anche qualche amico.\n\nConosci l'accordo, no? Tu mi copri le spalle e io ti porto al nascondiglio dei Defias. Ma faresti meglio a starmi vicino. La banda dei Defias ora vuole la mia testa. Se mi vedono con te, cercheranno di uccidermi.\n\nFammi sapere quando tu e gli amici che riesci a radunare siete pronti a partire.", "Che affari hai con me? Sono un uomo molto impegnato...", "Eccellente, {name}! Ora che sappiamo dove si nasconde, VanCleef è praticamente nostro.", 0x2a2224c0, 0x3c4fa4f6, 0xf3c6ce7f, 0xa49dc7ac, 0xd5d9b9c8, "....." },
  [166] = { "La Defias Brotherhood", "Uccidi Edwin VanCleef e porta la sua testa a Gryan Stoutmantle.", "Ti resta un ultimo compito. Edwin VanCleef deve essere assassinato. Anche se mi addolora condannare a morte un uomo, è per il bene della gente di Westfall che VanCleef venga messo a tacere una volta per tutte. Portami la testa del furfante quando avrai compiuto l'opera.", "Come va la caccia a Edwin VanCleef?", "{name}, il tuo coraggio è straordinario. La People's Militia ti ringrazia per il servizio reso alla gente di Westfall. Con la morte di VanCleef comincia la fine della Defias Brotherhood. Speriamo che presto la pace torni a benedire le pianure di questa bella terra.\n\nTi saluto, <Signore/Signora>!", 0x2a2224c0, 0xaf5696f5, 0xeeda81af, 0xb9d86261, 0x9f2be902, ".....", nil, nil, nil, nil, 0xf7825732 },
  [169] = { "RICERCATO: Gath'Ilzogg", "Uccidi Gath'Ilzogg e porta la sua testa a Magistrate Solomon, a Lakeshire, per la ricompensa.", "Ricercato! Gath'Ilzogg, capo degli attacchi dei Blackrock alla Stonewatch Keep e delle incursioni contro la municipalità di Lakeshire.\n\nGath'Ilzogg è estremamente pericoloso. Si dice che sia asserragliato nella fortezza appena conquistata, a tramare nuovi crimini del clan Blackrock contro l'umanità. L'infestazione degli orchi va stroncata a ogni costo. Una generosa ricompensa sarà data a qualunque anima coraggiosa porti la testa di Gath'Ilzogg a Magistrate Solomon.", "Cos'hai lì, {race}?", "Lavoro fantastico, {name}! Gath'Ilzogg guidava quei bruti in battaglia e ha ucciso molti umani innocenti. Abbiamo avuto giustizia. È il primo passo per riconquistare la fortezza per il regno di Stormwind!", 0x1fa3cb70, 0xdb0eb6e4, 0x8a4b873e, 0x46dc827d, 0x5c3ce0be, "....." },
  [176] = { "RICERCATO: \"Hogger\"", "Uccidi lo gnoll Hogger e porta il suo Huge Gnoll Claw a Marshal Dughan.", "Ricercato: Hogger\n\nUn enorme gnoll, Hogger, si aggira nei boschi della parte sud-occidentale di Elwynn. Ha avuto la meglio su tutti i tentativi di catturarlo.\n\nLa Stormwind Army ha messo una generosa taglia sullo gnoll. Per riscuotere la ricompensa, i cacciatori di taglie devono portare la prova della morte di Hogger a Marshal Dughan, a Goldshire.", "Sì, Hogger è stato una vera spina nel fianco per me e i miei uomini. Hai qualcosa da riferire su quella bestia?", "Ah! Ben fatto! Cominciavo a pensare che nessuno avrebbe abbattuto quel mostro!\n\nEcco a te, {name}. E grazie: quello gnoll mi stava facendo venire un mal di testa grande quanto la Blackrock Spire!", 0x9dcd29e7, 0x318a3a3b, 0xab83e5ae, 0xadee0c74, 0xc7de9815, "....." },
  [178] = { "Un recupero per Theocritus", "Porta il Faded Shadowhide Pendant a Theocritus the Mage.", "<Senti una voce senza corpo...>\n\nNon allarmarti. Sono Theocritus, High Mage della Tower Azora nella Elwynn Forest. Il ciondolo che tieni in mano è un mezzo di comunicazione tra gli Shadowhide Gnolls e il loro padrone, Morganth.\n\nDopo mesi di ricerche, credo di poter comunicare anch'io attraverso questi ciondoli. Se senti questo messaggio, il mio incantesimo è riuscito.\n\nPortami questo ciondolo e ti ricompenserò per il servizio.", "Ti ho parlato attraverso un ciondolo, dici? Mmm... dammelo, così posso studiarlo.", "Hai la mia gratitudine, {name}. Ho mandato quel messaggio agli Shadowhide Pendants settimane fa e lo credevo un fallimento. Ma sembra che l'incantesimo abbia raggiunto almeno alcuni ciondoli, con un notevole ritardo.\n\nCol tempo spero di imparare a lanciare un attacco attraverso i ciondoli, per immobilizzare gli Shadowhide Gnolls che li indossano.\n\nMa prima che sia possibile, temo servano molte altre ricerche.", 0xd1b6915b, 0xe9f541db, 0x7788c2a9, 0xdac36d0d, 0xd28bd097, "....." },
  [180] = { "RICERCATO: Lieutenant Fangore", "Uccidi Lieutenant Fangore e torna da Magistrate Solomon, a Lakeshire, con la sua zampa.", "Ricercato: Lieutenant Fangore\n\nNoto capo dello Shadowhide Gnoll Clan, al servizio del nemico della municipalità e del regno, Morganth. Per ordine di Magistrate Solomon, questo lurido traditore di Stormwind è ricercato morto. Mostra la sua zampa al magistrato come prova della sua morte.", "Quali notizie porti davanti alla corte?", "Dunque il malvagio Lieutenant Fangore è morto? Bella liberazione da quella lurida creatura. Sei molto <coraggioso/coraggiosa>, {class}. La municipalità di Lakeshire ti ringrazia per l'aiuto.", 0x8dd050b7, 0xeaf3268f, 0xeb39ff35, 0xb6305447, 0x338741ad, "....." },
  [184] = { nil, "Porta il Furlbrow's Deed a Farmer Furlbrow.", "Questo è l'atto di proprietà di una distesa di terreni agricoli a Westfall. È firmato da un certo Theodore Furlbrow e controfirmato dalla moglie, Verna. E sul retro ci sono parole scarabocchiate in fretta:\n\n\"Abbiamo fatto pressione su Furlbrow e ci siamo presi il suo atto. Pensavo potesse servirti, se volessi falsificarne uno per un posto tutto tuo.\n\nI Furlbrow non ci daranno fastidio. L'ultima volta che li ho visti stavano lasciando Westfall, bloccati con un carro rotto.\"\n\nPensi che i Furlbrow potrebbero rivolere il loro atto...", "Hai l'atto della mia fattoria?? Che bella notizia! Dei furfanti me l'hanno rubato giorni fa... credevo di averlo perso per sempre!\n\nTi prego, dammelo. Stiamo lasciando Westfall e non torneremo tanto presto, ma se torneremo, ci serviranno quelle carte...", "Grazie infinite, {name}! Come dicevo, queste terre non sono più adatte alla gente onesta, ma se le cose miglioreranno, questo atto ci permetterà di riprenderci la nostra terra.\n\nNon ho molto da offrirti, ma ecco: prendi questo.", nil, 0x11feda88, 0x57a4e970, 0x5eec9a09, 0x4f2a8d57, "m...." },
  [214] = { nil, "Scout Riell, alla Sentinel Hill Tower, vuole che tu le porti 10 Red Silk Bandanas.", "Non è un segreto che il marchio della banda dei Defias siano le loro Red Bandanas. Ma abbiamo scoperto che il materiale di cui sono fatte indica il grado di chi le porta.\n\nDetto questo, voglio che tu elimini quanti più membri di alto grado dei Defias puoi. Quelli di grado più alto si trovano di sicuro nel nascondiglio segreto di VanCleef. Quando hai finito, portami 10 Red Silk Bandanas come prova della loro morte e ti ricompenserò. Buona fortuna, {name}.", "Hai riconquistato la nostra terra dalla banda dei Defias? Se è così, mostrami 10 Red Silk Bandanas come prova.", "Ben fatto, {name}! A nome della People's Militia ti rendo onore per i tuoi sforzi. Presto, con l'aiuto di anime coraggiose come te, restituiremo questa terra alla sua gente.", nil, 0x16e9af40, 0xca668909, 0x9de63344, 0xb8efc2a9, "m...." },
  [219] = { "Disperso in azione", "Proteggi Corporal Keeshan durante il viaggio di ritorno a Redridge.", "Finalmente, amici dell'Alliance!\n\nAiuto... vi prego...\n\nL'ultima cosa che ricordo è che questi luridi orchi hanno sopraffatto il nostro reggimento. Quasi tutti gli uomini sono stati uccisi. Ho preso un forte colpo alla testa e poi è stato tutto buio. Ora sono prigioniero in questa caverna. Aiutatemi, sono ferito gravemente.\n\nMi servirà aiuto per tornare in paese... vi prego... siete la mia ultima speranza...", "Sì?", "Hai servito bene il regno, {class}. Grazie per aver aiutato Corporal Keeshan a fuggire da quei temibili Blackrock Orcs. Oggi sarai <ricompensato/ricompensata> per le tue azioni coraggiose.", 0xd4ba8881, 0x846a56f1, 0x9fe9b7bf, 0x0c07a888, 0x3364444e, "....." },
  [239] = { "La Westbrook Garrison chiede aiuto!", "Vai alla Westbrook Garrison e parla con Deputy Rainer.", "La guarnigione sul nostro confine occidentale ci avverte che gli gnoll e i ladri sono sempre più attivi. Chiedono che mandiamo altri soldati di Stormwind... ma non ne abbiamo da mandare!\n\nSe puoi aiutarci, ci farebbe comodo. Vai a parlare con Deputy Rainer alla Westbrook Garrison e senti di cosa ha bisogno.\n\nLa guarnigione è più avanti lungo la strada, a ovest. Dopo aver attraversato il ponte sul piccolo ruscello, la trovi sulla destra.", nil, "Ti manda Marshall Dughan, eh? Be', non fai parte dell'esercito, ma se ti manda Dughan per me va più che bene!\n\nLa nostra situazione è, a dir poco, tesa. Spero che tu possa darci una mano.", 0xdc5c2624, 0x2e02a498, 0x8d2938bf, nil, 0x3b449a23, "...m." },
  [244] = { "Gnoll alle porte", "Fai rapporto a Deputy Feldon.", "Salute, {class}. Ho il compito di pattugliare questo tratto di strada. Anche se per ora la strada è sicura, ho visto accampamenti di gnoll a nord e a est di qui.\n\nLakeshire deve sapere che gli gnoll stanno radunando le forze! Vai da Deputy Feldon a Lakeshire e parlagli degli gnoll. Fallo, e di sicuro Feldon ti offrirà la paga di un esploratore.\n\nDi solito Feldon ispeziona la zona a sud del ponte per Lakeshire.", nil, "Ci sono Redridge gnolls così vicino a Elwynn?? Potrebbero essere pronti ad avanzare nella nostra terra. Presto quelli di Lakeshire potrebbero non essere gli unici umani sotto assedio!\n\nEcco la tua paga, anche se ci porti notizie terribili. E arrivano in un brutto momento, perché non siamo attrezzati per affrontarle.", 0x8c8be2e9, 0x7bc054fc, 0xae1593a2, nil, 0x3e80651e, "...m." },
  [246] = { "Valutare la minaccia", "Uccidi 10 Redridge Mongrels e 6 Redridge Poachers, poi torna a fare rapporto a Deputy Feldon a Lakeshire.", "Non abbiamo uomini da mandare, ma bisogna fare qualcosa per quegli gnoll che mi hai segnalato.\n\nEsplora la parte meridionale di Redridge in cerca di gnoll. Tormentali, uccidi quelli che puoi e torna a riferirmi quanti sono e quanto è grave la minaccia che rappresentano. Troverai gli gnoll accampati lungo tutta la strada meridionale di Redridge.\n\nFallo per la Stormwind Army, {name}, e sarai <ricompensato/ricompensata>.", "Scusami, {name}, ma qui abbiamo molto da fare. Se non hai niente da riferire, devo pensare ad altro.", "<Deputy Feldon ascolta il tuo rapporto...>\n\nLì è accampato un bel numero di gnoll, e da quello che mi dici sono dei duri. Non dev'essere stato facile raccogliere queste informazioni.\n\nEcco a te, {name}. Ti siamo grati per l'aiuto.\n\nE se non l'hai già fatto, parla con Marshal Marris e con Magistrate Solomon, a Lakeshire. La nostra situazione è sempre più disperata: di sicuro tutti e due avranno bisogno di te.", 0xcdd38f62, 0x1de28477, 0x75c1cdab, 0xfd431e78, 0x3a73678c, "....." },
  [248] = { "Guardare più lontano", "Sali sulla torre di guardia intatta accanto alla Stonewatch Keep.\n\nTrova un contenitore adatto in cui mettere il Glyph of Azora.", "Ho tenuto d'occhio la Tower of Ilgalar e percepisco che Morganth è in conflitto con gli orchi della Stonewatch Keep. Non conosco il motivo della loro contesa, ma puoi aiutarmi a svelare questo mistero.\n\nPrendi un altro Glyph of Azora, poi sali in cima alla torre di guardia intatta accanto alla Stonewatch Keep.\n\nTrova un oggetto adatto su cui posare il glifo. Un forziere o un vaso, un posto dove il glifo non venga notato, andrà bene per il mio scopo.", "Questo vaso un tempo conteneva un liquore maleodorante, ma ora giace vuoto e dimenticato su un paio di barili.", "È un recipiente adatto per il Glyph of Azora, e permetterà a Theocritus di scrutare le menti dentro la Stonewatch Keep.", 0x6310d65d, 0x375e6926, 0x7c764f66, 0x08216341, 0x02b3cbef, "....." },
  [249] = { nil, "Sconfiggi Morganth.\n\nPorta il suo Pendant of Shadow a Theocritus, alla Tower of Azora nella Elwynn Forest.", "Dopo lunghe osservazioni, ho scoperto i piani di Morganth.\n\nCerca la Scythe of Elune... e forse l'ha trovata! Se è così, presto le Redridge Mountains e il regno di Stormwind sentiranno la sua oscura potenza.\n\nNon sono pronto ad affrontare Morganth, ma temo che vada fermato subito. Perciò devi entrare nella Tower of Ilgalar e affrontarlo.\n\nSconfiggilo e portami il suo Pendant of Shadow. Fallo, e il regno ti sarà molto debitore.", "Presto, {name}, prima che il mio timore che Morganth estenda il suo potere si avveri!", "Hai fatto bene, {name}. Sconfiggendo lo stregone Morganth, hai salvato Stormwind da un grave pericolo.\n\nTi offro questa ricompensa con grande umiltà. E ti augurerei la pace, se questi fossero tempi di pace.\n\nInvece ti auguro fortuna nelle tue prove, e vittoria nei conflitti che verranno.", nil, 0x879964dd, 0x12522098, 0x0143479a, 0x425a6647, "m...." },
  [345] = { "Scorte d'inchiostro", "Parla con Foreman Oslow a Lakeshire e chiedigli del Rethban Iron Ore.", "Volevo finire la mia copia di The Stresses of Iron, ma...\n\nVedi, faccio da me l'inchiostro per i libri che copio. È una mia ricetta: non cola, non sbava e asciuga in fretta. Purtroppo asciuga troppo in fretta! L'ultima partita si è seccata prima che finissi di copiare, e non ho avuto occasione di farne dell'altro!\n\nPer farne altro mi serve del Rethban Iron Ore dalle Redridge Mountains. Di solito me lo fornisce Foreman Oslow, a Lakeshire.", nil, "Ti serve cosa?? Forse non te ne sei <accorto/accorta>, ma siamo impegnati a rafforzare le difese di Lakeshire e a riparare i danni dei recenti attacchi degli orchi. Se ti serve del Rethban Iron Ore, dovrai procurartelo da <solo/sola>!", 0x6436fa89, 0x9f82018f, 0xf8e115c5, nil, 0x6eaa5bf6, "...m." },
  [346] = { "Ritorno da Kristoff", "Torna da Brother Kristoff nella Cathedral Square e consegnagli il libro The Stresses of Iron.", "Ora che ho finito di copiare il libro, ecco l'originale di Stresses of Iron. Grazie per la pazienza, e se vedi Milton, digli che mi dispiace per il lungo ritardo.", "Sei <riuscito/riuscita> a trovare il libro?", "È proprio quello! Grazie, {name}. Che la Luce risplenda sul tuo corpo e sul tuo spirito!", 0x7914bcc7, 0xaffc7d2d, 0xa9d0a831, 0xf44efc87, 0xcfcb4f09, "....." },
  [347] = { nil, "Raccogli 5 carichi di Rethban Ore e portali a Brother Paxton, nella Northshire Library.", "La Rethban Ore prende il nome dall'uomo che la trovò per primo, Bart Rethban. Una volta fusa non è resistente come il ferro, ma il minerale ha un colore scuro e opaco che alcuni scribi usano per le loro tinture. Si trova nelle Rethban Caverns, a nord di qui.\n\nDi solito ne abbiamo un po' in magazzino, ma siamo troppo presi a prepararci agli attacchi degli orchi per raccoglierne. E poi... ora nelle Rethban Caverns vivono i Redridge Gnolls, e i loro Drudgers il minerale se lo raccolgono da soli.\n\nQuindi, se te ne serve, dovrai procurartelo da <solo/sola>.", "Hai la Rethban Ore?", "Oh, splendido! Posso usare questo minerale per la mia tintura, e poi finire di copiare The Stresses of Iron.\n\nGrazie, {name}!", nil, 0x66b7c48d, 0xcc491e42, 0xd2e294d7, 0x1dd5b437, "m...." },
  [361] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [386] = { "Chi la fa l'aspetti...", "Porta la testa di Targorr the Dread a Guard Berton, a Lakeshire.", "Targorr the Dread era il boia supremo al servizio di Gath'Ilzogg. I suoi metodi erano spietati, persino per gli standard di quei luridi orchi. Uomini che avevano combattuto con coraggio per difendere il regno venivano torturati a suo capriccio. Ora è rinchiuso nella Stormwind Stockade, condannato a morte. Eppure qualcosa non torna. Uno dei nobili della burocrazia ha sospeso la sua esecuzione. Sono certo che c'è sotto qualcosa di losco.\n\nMetti fine a Targorr the Dread, {name}. Vai alla Stockade e decapitalo prima che l'inganno abbia la meglio.", "Sei già <stato/stata> a Stormwind, alla Stockade? Temo che l'inganno che ha tenuto in vita Targorr the Dread così a lungo finirà per ridargli la libertà. È stato condannato a morte, {name}, non a fare da pedina politica per il capriccio di un nobile.", "Targorr the Dread ha finalmente incontrato il suo destino. Io, per primo, sono contento di sapere che quella bestia ora sa cosa vuol dire trovarsi nella morsa spietata della morte. Hai fatto bene, {name}. A volte la giustizia più vera si trova solo fuori dall'aula di tribunale, oltre la vista annebbiata della politica.", 0x985b5c1d, 0x0bd13fa2, 0x9d18b187, 0x4b424f22, 0x4701141d, "....." },
  [398] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [567] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [783] = { "Una minaccia interna", "Parla con Marshal McBride.", "Spero che tu abbia stretto bene la cintura, giovane {class}, perché qui a Northshire c'è del lavoro da fare.\n\nE non parlo di lavorare i campi.\n\nLe guardie di Stormwind faticano a mantenere la pace, con tanti di noi in terre lontane e tante minacce sempre più vicine. Per questo arruoliamo chiunque sia disposto a difendere la propria casa. E la propria alleanza.\n\nSe sei qui per rispondere alla chiamata, parla con il mio superiore, Marshal McBride. È dentro l'abbazia, alle mie spalle.", nil, "Ah, bene. Un'altra recluta. Di questi tempi ne arrivano tante.\n\nSpero che basti.\n\nLe terre degli umani sono minacciate dall'esterno, e molte delle nostre forze sono state mandate lontano. Questo, a sua volta, lascia spazio a gruppi corrotti e fuorilegge che prosperano entro i nostri confini.\n\nCombattiamo una battaglia su molti fronti, {name}. Preparati a una lunga campagna.", 0x5dfca6f5, 0x4ec936be, 0x0ab5d4f4, nil, 0x031c7505, "...m." },
  [819] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
  [863] = { "La fuga", nil, nil, nil, nil, 0x437cedda, nil, nil, nil, nil, ".mmmm" },
  [898] = { nil, nil, nil, "Sì?", nil, nil, nil, nil, 0x0c07a888, nil, "mmm.m" },
})
